package com.example

import com.example.ExamQuestionHelper.QSpec

/**
 * Curated Geography Live Exam Hall Bank — Domain 5:
 * ජනගහන භූගෝල විද්‍යාව හා ජනාවාස (Population & Settlement Geography)
 */
internal object GeographyLiveExamPopulationBank {
  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun populationAndSettlementQuestions(): List<QSpec> {
    val t = "ජනගහන භූගෝල විද්‍යාව හා ජනාවාස"
    return listOf(
      q(t, "යම් රටක හෝ කලාපයක වර්ග කිලෝමීටරයක් තුළ ජීවත් වන සාමාන්‍ය ජන සංඛ්‍යාව හඳුන්වනු ලබන්නේ කුමන නමින්ද?",
        "ජන ඝනත්වය (Population Density)", "ජනගහන වර්ධන වේගය", "යැපුම් අනුපාතය", "උපත් අනුපාතය",
        "ජන ඝනත්වය = මුළු ජනගහනය ÷ මුළු භූමි ප්‍රමාණය (වර්ග කි.මී.) ලෙස ගණනය කෙරේ."),
      q(t, "භූමි ප්‍රමාණය හා මුළු ජනගහනය සැලකීමේදී වර්ග කිලෝමීටරයට ජනගහනය ගණනය කරන 'අංක ගණිතමය ජන ඝනත්වය'ට (Arithmetic Density) වඩා 'භෞතික විද්‍යාත්මක ජන ඝනත්වය' (Physiological Density) වැදගත් වන්නේ ඇයි?",
        "වගා කළ හැකි කෘෂිකාර්මික ඉඩම් ඒකකයක් මත ජනගහනය ඇති කරන පීඩනය නිවැරදිව පෙන්වන බැවින්", "කාන්තාර බිම් පමණක් ගණන් ගන්නා බැවින්", "සාගර ප්‍රමාණය බෙදන බැවින්", "වයස අනුව බෙදන බැවින්",
        "මුළු ජනගහනය වගා කළ හැකි ඉඩම් ප්‍රමාණයෙන් බෙදීමෙන් ආහාර හා ඉඩම් මත පවතින සැබෑ තෙරපුම මනිනු ලැබේ."),
      q(t, "'කෘෂිකාර්මික ජන ඝනත්වය' (Agricultural Density) යනු කුමන අනුපාතයද?",
        "කෘෂිකාර්මික ජනගහනය (ගොවීන්) සහ වගා කළ හැකි ඉඩම් ප්‍රමාණය අතර අනුපාතය", "නාගරික ජනගහනය සහ වනාන්තර අතර අනුපාතය", "ධීවරයන් සහ මුහුදු ප්‍රමාණය අතර අනුපාතය", "මුළු ජනගහනය සහ කර්මාන්තශාලා ගණන",
        "මෙය යම් රටක කෘෂිකර්මාන්තයේ යාන්ත්‍රිකරණ මට්ටම හා ගොවි පවුල් මත රඳා පැවැත්ම පෙන්නුම් කරයි."),
      q(t, "ජනගහන භූගෝල විද්‍යාවේ 'අශුද්ධ උපත් අනුපාතය' (Crude Birth Rate - CBR) නිර්වචනය කරනු ලබන්නේ කෙසේද?",
        "වසරක් තුළ ජනගහනයේ සෑම පුද්ගලයන් 1,000 කටම සිදුවන සජීවී උපත් සංඛ්‍යාව", "පුද්ගලයන් 100 කට උපත් ගණන", "දශකයකට වරක් උපදින ගණන", "කාන්තාවකට සිටින මුළු දරුවන් ගණන",
        "CBR = (වසරේ සජීවී උපත් ÷ මධ්‍ය වාර්ෂික ජනගහනය) × 1,000 ලෙස ප්‍රකාශ කෙරේ."),
      q(t, "'අශුද්ධ මරණ අනුපාතය' (Crude Death Rate - CDR) අඩු වී 'උපත් අනුපාතය' (CBR) ඉහළ මට්ටමක පවතින විට සිදුවන ජනගහන ක්‍රියාවලිය කුමක්ද?",
        "ස්වාභාවික ජනගහන වර්ධන වේගය (Natural Increase Rate) සීඝ්‍රයෙන් ඉහළ යාම (ජනගහන පිපිරුම)", "ජනගහනය ක්ෂණිකව අඩුවීම", "ශුන්‍ය වර්ධනය", "සෘණ වර්ධනය",
        "ස්වාභාවික වර්ධන අනුපාතය = CBR − CDR වන බැවින් උපත් වැඩි වී මරණ අඩු වීමේදී ජනගහනය වේගයෙන් වැඩි වේ."),
      q(t, "'ළදරු මරණ අනුපාතය' (Infant Mortality Rate - IMR) මගින් මනිනු ලබන්නේ කුමක්ද?",
        "වසරක් තුළ සජීවී උපත් 1,000 කින් වයස අවුරුදු 1 සම්පූර්ණ වීමට පෙර මියයන ළදරුවන් සංඛ්‍යාව", "වයස අවුරුදු 5 ට වැඩි දරුවන්ගේ මරණ", "මව්වරුන්ගේ මරණ සංඛ්‍යාව", "සමස්ත වැඩිහිටි මරණ සංඛ්‍යාව",
        "IMR යනු රටක මාතෘ හා ළමා සෞඛ්‍ය සේවා, පෝෂණය හා සනීපාරක්ෂාව මැනීමේ ප්‍රධාන දර්ශකයකි."),
      q(t, "'මුළු සාඵල්‍යතා අනුපාතය' (Total Fertility Rate - TFR) 'ප්‍රතිස්ථාපන මට්ටම' (Replacement Level) ලෙස සැලකෙන්නේ කාන්තාවකට සාමාන්‍යයෙන් දරුවන් කී දෙනෙකු සිටින විටද?",
        "දරුවන් 2.1 ක් පමණ වන විට", "දරුවන් 5.0 ක් වන විට", "දරුවන් 1.0 ක් වන විට", "දරුවන් 0.5 ක් වන විට",
        "සංක්‍රමණ රහිතව දෙමාපියන් දෙදෙනා ප්‍රතිස්ථාපනය වී ජනගහනය ස්ථාවරව පැවතීමට TFR ≈ 2.1 අවශ්‍ය වේ."),
      q(t, "ජන විකාශන සංක්‍රාන්ති ආකෘතියේ (Demographic Transition Model - DTM) 'පළමු අදියරේ' (Stage 1 - ඉහළ ස්ථාවර) ලක්ෂණ මොනවාද?",
        "උපත් අනුපාතය සහ මරණ අනුපාතය යන දෙකම ඉතා ඉහළ මට්ටමක පැවතීම නිසා ජනගහන වර්ධනය ඉතා මන්දගාමී හෝ උච්චාවචනය වීම", "උපත් හා මරණ දෙකම පහළ වීම", "මරණ අනුපාතය ශුන්‍ය වීම", "ජනගහනය සෘණ වීම",
        "වසංගත, සාගත, යුද්ධ හා ප්‍රාථමික වෛද්‍ය පහසුකම් නිසා පූර්ව-කාර්මික සමාජ මෙම අදියරේ පැවතුණි."),
      q(t, "ජන විකාශන සංක්‍රාන්ති ආකෘතියේ (DTM) 'දෙවන අදියරේදී' (Stage 2 - මුල් ප්‍රසාරණය) ජනගහනය වේගයෙන් වැඩි වීමට ප්‍රධාන හේතුව කුමක්ද?",
        "සනීපාරක්ෂාව, පිරිසිදු ජලය, එන්නත් හා ආහාර සැපයුම දියුණු වීමෙන් මරණ අනුපාතය වේගයෙන් පහත වැටුණද උපත් අනුපාතය තවදුරටත් ඉහළ මට්ටමක පැවතීම", "උපත් අනුපාතය ශුන්‍ය වීම", "සියලු දෙනා විදේශගත වීම", "ආයු අපේක්ෂාව අඩු වීම",
        "18 වන සියවසේ කාර්මික විප්ලවයෙන් පසු යුරෝපයද, 20 වන සියවසේ මැද සිට සංවර්ධනය වෙමින් පවතින රටවල්ද මෙම අදියර පසු කළේය."),
      q(t, "ජන විකාශන සංක්‍රාන්ති ආකෘතියේ 'තෙවන අදියරේ' (Stage 3 - පසු ප්‍රසාරණය) සිදුවන ප්‍රධාන වෙනස්කම කුමක්ද?",
        "කාන්තා අධ්‍යාපනය, නාගරීකරණය, ළදරු මරණ අඩුවීම හා පවුල් සැලසුම් නිසා උපත් අනුපාතය පහත වැටීමට පටන් ගැනීම", "මරණ අනුපාතය නැවත ඉහළ යාම", "නාගරික ජනගහනය ගමට යාම", "වෛද්‍ය සේවා බිඳ වැටීම",
        "මෙහිදී ජනගහන වර්ධන වේගය ක්‍රමයෙන් මන්දගාමී වේ."),
      q(t, "ජන විකාශන සංක්‍රාන්ති ආකෘතියේ 'සිව්වන අදියරේ' (Stage 4 - පහළ ස්ථාවර) සහ 'පස්වන අදියරේ' (Stage 5) රටවලට උදාහරණ වන්නේ කුමන රටවල්ද?",
        "ජපානය, ජර්මනිය, ඉතාලිය සහ ස්වීඩනය වැනි සංවර්ධිත රටවල්", "නයිජර් සහ චැඩ්", "ඇෆ්ගනිස්ථානය සහ යේමනය", "කොංගෝ සහ උගන්ඩාව",
        "පස්වන අදියරේදී (උදා: ජපානය) උපත් අනුපාතය මරණ අනුපාතයට වඩා අඩු වී ජනගහනය ස්වාභාවිකව අඩු වේ (සෘණ වර්ධනය)."),
      q(t, "'ජනගහන පිරමීඩයක්' (Population Pyramid / Age-Sex Pyramid) මගින් නිරූපණය කරනු ලබන්නේ කුමන දත්තද?",
        "යම් ජනගහනයක වයස් කාණ්ඩ (Age Groups) සහ ස්ත්‍රී-පුරුෂ සංයුතිය (Sex Structure)", "ආදායම් බෙදී යාම පමණි", "වාර්ගික විවිධත්වය පමණි", "රැකියා වියුක්තිය පමණි",
        "පිරමීඩයේ පළල පාදම, මැද හා මුදුන රටක උපත්, මරණ, ආයු අපේක්ෂාව හා යැපුම් බර පිළිබිඹු කරයි."),
      q(t, "පුළුල් පාදමක් සහ ඉතා පටු තියුණු මුදුනක් සහිත ත්‍රිකෝණාකාර ජනගහන පිරමීඩයක් (Expansive Pyramid) පෙන්නුම් කරන්නේ කුමක්ද?",
        "ඉහළ උපත් අනුපාතයක්, වේගවත් ජනගහන වර්ධනයක්, ඉහළ තරුණ/ළමා අනුපාතයක් සහ අඩු ආයු අපේක්ෂාවක් (සංවර්ධනය වෙමින් පවතින රටක්)", "වයස්ගත වන ජනගහනයක්", "සෘණ ජනගහන වර්ධනයක්", "අඩු උපත් අනුපාතයක්",
        "උප-සහරා අප්‍රිකානු රටවල් බොහොමයක මෙවැනි පුළුල් පාදමක් සහිත පිරමීඩ දක්නට ලැබේ."),
      q(t, "පටු පාදමක් සහ මැද/ඉහළ කොටස් පුළුල් වූ 'බඳුනක හෝ සීනුවක හැඩැති' (Constrictive) ජනගහන පිරමීඩයක් ඇති රටක ප්‍රධාන සමාජ-ආර්ථික අභියෝගය කුමක්ද?",
        "ශ්‍රම බලකාය හැකිලීම, වයස්ගත ජනගහනය ඉහළ යාම සහ විශ්‍රාම වැටුප්/සෞඛ්‍ය වියදම් ඉහළ යාම", "ප්‍රාථමික පාසල් ඉඩ මදිවීම", "ළමා උපත් පිපිරුම", "වැඩිහිටියන් අඩු වීම",
        "ජපානය, දකුණු කොරියාව හා යුරෝපීය රටවල් මෙම වයස්ගත වීමේ (Ageing) අභියෝගයට මුහුණ දෙයි."),
      q(t, "'ජන විකාශන පාරිතෝෂිකය' (Demographic Dividend) යනු කුමක්ද?",
        "උපත් අනුපාතය අඩු වීමත් සමඟ යැපෙන ළමුන් ගණන අඩු වී වැඩ කරන වයසේ (15–64) ශ්‍රම බලකාය ඉහළ ප්‍රතිශතයකට පැමිණීමෙන් ආර්ථික වර්ධනයට ලැබෙන වාසිය", "රජයෙන් නොමිලේ ආහාර බෙදීම", "ජනගහනය විදේශගත කිරීම", "විශ්‍රාමිකයන් වැඩිවීම",
        "නැගෙනහිර ආසියානු 'ආර්ථික ව්‍යාඝ්‍ර' රටවල් සිය සංවර්ධනය සඳහා මෙම කාල පරිච්ඡේදය සාර්ථකව භාවිත කළේය."),
      q(t, "'යැපුම් අනුපාතය' (Dependency Ratio) ගණනය කිරීමේදී 'යැපෙන ජනගහනය' ලෙස සාමාන්‍යයෙන් සලකනු ලබන වයස් කාණ්ඩ මොනවාද?",
        "වයස අවුරුදු 0–14 (ළමා) සහ අවුරුදු 65 ට වැඩි (වැඩිහිටි) ජනගහනය", "වයස අවුරුදු 20–50 අතර පිරිස", "වයස අවුරුදු 18–35 අතර පිරිස", "පාසල් ගුරුවරුන් පමණි",
        "මෙම කාණ්ඩ දෙකේ එකතුව වැඩ කරන වයසේ (15–64) ජනගහනයෙන් බෙදා 100 න් ගුණ කිරීමෙන් යැපුම් අනුපාතය ලබා ගනී."),
      q(t, "'ස්ත්‍රී පුරුෂ අනුපාතය' (Sex Ratio) අසාමාන්‍ය ලෙස පිරිමින්ට වාසිදායක වී ඇති (උදා: පුරුෂයන් 150–250 කට කාන්තාවන් 100) ගල්ෆ් කලාපයේ රටවල (කටාර්, එක්සත් අරාබි එමීර් රාජ්‍යය) ඊට හේතුව කුමක්ද?",
        "ඉදිකිරීම් හා තෙල් කර්මාන්ත සඳහා විශාල වශයෙන් තරුණ පිරිමි විදේශීය ශ්‍රමිකයන් සංක්‍රමණය වීම", "ජානමය වෙනසක්", "කාන්තාවන්ට සීතල දේශගුණය නොගැළපීම", "යුද්ධය නිසා කාන්තාවන් මියයාම",
        "රැකියා සඳහා පැමිණෙන කෙටි කාලීන පිරිමි සංක්‍රමණික ශ්‍රමිකයන් නිසා ජනගහන පිරමීඩයේ පිරිමි පැත්ත ඉදිරියට නෙරා ඇත."),
      q(t, "'ජනගහනය දෙගුණ වීමේ කාලය' (Doubling Time) '70 රීතිය' (Rule of 70) අනුව ආසන්න වශයෙන් ගණනය කරන්නේ කෙසේද?",
        "70 ÷ වාර්ෂික ජනගහන වර්ධන ප්‍රතිශතය (%)", "100 × වර්ධන ප්‍රතිශතය", "365 ÷ උපත් අනුපාතය", "ජනගහනය ÷ 2",
        "උදාහරණයක් ලෙස වාර්ෂික වර්ධන වේගය 2% නම් ජනගහනය දෙගුණ වීමට ආසන්න වශයෙන් 70 ÷ 2 = වසර 35 ක් ගතවේ."),
      q(t, "'තෝමස් මැල්තස්' (Thomas Malthus - 1798) සිය ජනගහන න්‍යායෙන් ඉදිරිපත් කළ ප්‍රධාන තර්කය කුමක්ද?",
        "ජනගහනය ගුණෝත්තර ශ්‍රේණියකින් (1, 2, 4, 8...) වර්ධනය වන විට ආහාර නිෂ්පාදනය අංක ගණිතමය ශ්‍රේණියකින් (1, 2, 3, 4...) පමණක් වැඩි වන බැවින් අනාගතයේදී සාගත හා අර්බුද ඇති වන බව", "තාක්ෂණයෙන් ආහාර අනන්ත ලෙස වැඩි වන බව", "ජනගහනය ඉබේම අඩුවන බව", "සාගර මත ගොවිතැන් කරන බව",
        "මැල්තස්ගේ න්‍යායට ප්‍රතිවිරුද්ධව එස්තර් බොස්රප් (Ester Boserup) පෙන්වා දුන්නේ ජනගහන පීඩනය කෘෂි නවෝත්පාදන ඇති කරන බවයි."),
      q(t, "ජනගහන විද්‍යාවේ 'ප්‍රශස්ත ජනගහනය' (Optimum Population) යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "යම් රටක පවතින සම්පත් හා තාක්ෂණය උපරිම කාර්යක්ෂමතාවයෙන් භාවිත කර ඒක පුද්ගල ආදායම හා ජීවන තත්ත්වය උපරිම කළ හැකි සුදුසුම ජන සංඛ්‍යාව", "ලෝකයේ වැඩිම ජනගහනය සිටින තත්ත්වය", "ජනගහනය ශුන්‍ය වූ තත්ත්වය", "රැකියා වියුක්තිය 50% ක් වන තත්ත්වය",
        "මීට වඩා ජනගහනය අඩු වීම 'ඌන ජනගහනය' (Underpopulation) ලෙසත් වැඩි වීම 'අධි ජනගහනය' (Overpopulation) ලෙසත් හැඳින්වේ."),
      q(t, "සංක්‍රමණ භූගෝල විද්‍යාවේදී මිනිසුන් තම මුල් පදිංචි ස්ථානය අතහැර යාමට පොළඹවන 'තල්ලු සාධක' (Push Factors) වලට උදාහරණ මොනවාද?",
        "රැකියා හිඟය, දිළිඳුකම, යුද ගැටුම්, දේශපාලන පීඩනය සහ නියඟ/ගංවතුර වැනි ස්වාභාවික ආපදා", "ඉහළ වැටුප් සහ උසස් විශ්වවිද්‍යාල", "සාමකාමී පරිසරය", "නවීන සෞඛ්‍ය පහසුකම්",
        "ඊට ප්‍රතිවිරුද්ධව නව ස්ථානයකට ආකර්ෂණය කරගන්නා වාසිදායක සාධක 'ඇදගැනීමේ සාධක' (Pull Factors) ලෙස හැඳින්වේ."),
      q(t, "සංක්‍රමණය පිළිබඳ 'බුද්ධි ගලනය' (Brain Drain) යන්නෙන් විස්තර කෙරෙන සංසිද්ධිය කුමක්ද?",
        "වෛද්‍යවරුන්, ඉංජිනේරුවන් හා විද්‍යාඥයන් වැනි උසස් අධ්‍යාපනය හා නිපුණතා ලත් වෘත්තිකයන් වැඩි වැටුප් හා පහසුකම් සොයා සංවර්ධනය වෙමින් පවතින රටවලින් සංවර්ධිත රටවලට සංක්‍රමණය වීම", "නුපුහුණු කම්කරුවන් ආපසු පැමිණීම", "සංචාරකයන් පැමිණීම", "වන සතුන් සංක්‍රමණය වීම",
        "බුද්ධි ගලනය මව් රටට පුහුණු මානව සම්පත අහිමි කළද, විදේශ ප්‍රේෂණ (Remittances) මගින් විදේශ විනිමය ගෙන එයි."),
      q(t, "'අභ්‍යන්තර අවතැන් වූවන්' (Internally Displaced Persons - IDPs) සහ 'සරණාගතයන්' (Refugees) අතර ඇති ප්‍රධාන වෙනස කුමක්ද?",
        "සරණාගතයන් ජාත්‍යන්තර දේශසීමාවක් පසු කර වෙනත් රටකට පලා යන අතර අභ්‍යන්තර අවතැන් වූවන් තම රටේ දේශසීමාව ඇතුළතම ආරක්ෂිත පෙදෙසකට යයි", "සරණාගතයන් රට ඇතුළේම සිටී", "දෙගොල්ලන්ම සංචාරකයන් වේ", "වෙනසක් නැත",
        "එක්සත් ජාතීන්ගේ සරණාගත කොමසාරිස් කාර්යාලය (UNHCR) මොවුන්ගේ අයිතිවාසිකම් හා සුබසාධනය පිළිබඳ කටයුතු කරයි."),
      q(t, "කාලීන රැකියා හෝ වගා කටයුතු සඳහා වසරේ එක් කාලයකදී වෙනත් ප්‍රදේශයකට ගොස් නැවත පැමිණීම හඳුන්වන්නේ කුමන සංක්‍රමණ වර්ගය ලෙසද?",
        "සෘතුමය සංක්‍රමණය (Seasonal Migration / Transhumance)", "ස්ථිර විගමනය", "බලහත්කාර සංක්‍රමණය", "අන්තර් මහාද්වීපික සංක්‍රමණය",
        "උදාහරණයක් ලෙස ඇල්ප්ස් හෝ හිමාලයානු කඳුකරයේ ගොපල්ලන් ගිම්හානයේ උස් තණබිම්වලට හා ශීත ඍතුවේ නිම්නවලට සතුන් ගෙන යාම."),
      q(t, "'පෙරළි සංක්‍රමණය' (Step Migration) පිළිබඳව අර්නස්ට් රැවෙන්ස්ටයින් (E.G. Ravenstein) පැහැදිලි කළේ කුමක්ද?",
        "ග්‍රාමීය ප්‍රදේශයක සිට පුද්ගලයෙකු එකවර විශාල අගනුවරට නොගොස්, ප්‍රථමයෙන් අසල කුඩා නගරයකටත් ඉන්පසු ප්‍රාදේශීය නගරයටත් අවසානයේ මහා නගරයටත් පියවරෙන් පියවර සංක්‍රමණය වීම", "පඩිපෙළක් නැගීම", "විදේශයක සිට ගමට පැමිණීම", "දිනපතා දුම්රියෙන් යාම",
        "බොහෝ සංක්‍රමණ කෙටි දුරවලින් සිදුවන බව රැවෙන්ස්ටයින්ගේ සංක්‍රමණ නීති පෙන්වා දෙයි."),
      q(t, "ගමේ සිට නගරයට නොයා රැකියා හෝ අධ්‍යාපනය සඳහා දිනපතා උදේ පැමිණ සවස ආපසු නිවසට යන ජන චලනය හඳුන්වන්නේ කෙසේද?",
        "දෛනික ගමනාගමනය / සංචරණය (Commuting / Daily Circulation)", "ස්ථිර සංක්‍රමණය", "නාගරික ක්ෂය වීම", "අවතැන් වීම",
        "නාගරික ප්‍රදේශවල තදාසන්න ප්‍රදේශ (Suburbs) දියුණු වීමත් සමඟ දෛනික ගමනාගමනය විශාල ලෙස ඉහළ ගොස් ඇත."),
      q(t, "'ජනගහන විසරණය' (Population Distribution) ගෝලීය වශයෙන් ඉතා අසමතුලිත වීමට බලපාන ප්‍රධාන භෞතික සාධක මොනවාද?",
        "භූ විෂමතාව (පැතලි තැනිතලා), මධ්‍යස්ථ දේශගුණය, සාරවත් පස සහ මිරිදිය ජල සැපයුම", "ජාතික කොඩියේ වර්ණය", "ක්‍රීඩාංගණ ගණන", "හඳේ කලාප",
        "ලෝක ජනගහනයෙන් ~90% ක් උතුරු අර්ධගෝලයේ ජීවත් වන අතර ඉන් වැඩි කොටසක් වෙරළබඩ තැනිතලා හා ගංගා නිම්න ආශ්‍රිතව සංකේන්ද්‍රණය වී ඇත."),
      q(t, "ලෝකයේ 'ප්‍රධාන ජනගහන සංකේන්ද්‍රණ කලාප' (Major Population Clusters) හතර කවරේද?",
        "නැගෙනහිර ආසියාව, දකුණු ආසියාව, ගිනිකොණදිග ආසියාව සහ යුරෝපය", "ඇන්ටාක්ටිකාව, ග්‍රීන්ලන්තය, සහරා හා ඇමසන්", "ඔස්ට්‍රේලියාව, ඇලස්කාව, සයිබීරියාව හා ගෝබි", "අයිස්ලන්තය, මැඩගස්කරය, චිලී හා කැනඩාව",
        "නැගෙනහිර හා දකුණු ආසියාවේ පමණක් ලෝක ජනගහනයෙන් අඩකට ආසන්න ප්‍රමාණයක් ජීවත් වේ."),
      q(t, "දකුණු ආසියාවේ හා නැගෙනහිර ආසියාවේ ඉන්දු-ගංගා, යැංසි හා හොවැංහෝ ගංගා නිම්නවල අධික ජන ඝනත්වයක් බිහිවීමට පදනම් වූ ප්‍රධාන සාධකය කුමක්ද?",
        "සාරවත් දියළු පස (Alluvial Soil), මෝසම් ජලය හා කන්න කිහිපයක් දැඩි වී වගා කිරීමට හැකිවීම", "රන් ආකර බහුල වීම", "සීතල හිම කඳු තිබීම", "විශාල තෙල් නිධි පැවතීම",
        "තෙත් වී වගාව (Intensive Wet Rice Cultivation) කුඩා බිම් ප්‍රමාණයකින් විශාල ජනගහනයක් පෝෂණය කිරීමට සමත් විය."),
      q(t, "යුරෝපයේ (රුර්, බෙල්ජියම, නෙදර්ලන්තය, එක්සත් රාජධානිය) අධික ජන ඝනත්වයක් බිහිවීමට බලපෑ ඓතිහාසික සාධකය ආසියාවට වඩා වෙනස් වන්නේ කෙසේද?",
        "කෘෂිකාර්මික සාධකවලට වඩා කාර්මික විප්ලවය, ගල් අඟුරු-යපස් නිධි, කර්මාන්තශාලා සහ වාණිජ වෙළඳ නගර බිහිවීම", "තේ වගාව නිසා", "කාන්තාර පැවතීම නිසා", "සම්පූර්ණයෙන් ධීවර කර්මාන්තය නිසා",
        "බටහිර යුරෝපයේ ජනගහනයෙන් 75%–85% කට වඩා නාගරික කාර්මික හා සේවා අංශවල ජීවත් වේ."),
      q(t, "කැනඩාව, රුසියාවේ සයිබීරියාව සහ ග්‍රීන්ලන්තය වැනි ඉහළ අක්ෂාංශ ප්‍රදේශ 'විරල ජනගහන කලාප' (Sparse Population) වීමට හේතුව කුමක්ද?",
        "අධික ශීතල, කෙටි වගා කාලය සහ නිත්‍ය තුහින (Permafrost) පස", "අධික උණුසුම", "ගිනිකඳු පිපිරීම් පමණි", "වනාන්තර නොමැති වීම",
        "ලෝක භූමි ප්‍රමාණයෙන් විශාල කොටසක් වසාගෙන සිටියද මෙම ධ්‍රැව ආසන්න පෙදෙස්වල වෙසෙන්නේ ඉතා සුළු ජනගහනයකි."),
      q(t, "'ජනගහන මධ්‍යස්ථානය' (Mean Center of Population) යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "රටක සියලුම පදිංචිකරුවන්ගේ බර සමතුලිත වන භූගෝලීය සමබරතා ලක්ෂ්‍යය", "රටේ අගනුවර පමණි", "වැඩිම උසැති කන්ද", "රටේ විශාලතම රෝහල",
        "ජනගහනය වෙනත් කලාපයකට සංක්‍රමණය වන විට මෙම මධ්‍යස්ථානය එම දිශාවට මාරු වේ."),
      q(t, "ලෝකයේ වර්තමාන ජනගහන ප්‍රවණතා අනුව, ඉන්දියාව චීනය අභිබවා ලොව වැඩිම ජනගහනය සිටින රට බවට පත්වූයේ කුමන සාධක නිසාද?",
        "චීනයේ දිගුකාලීන 'එක් දරු ප්‍රතිපත්තිය' නිසා උපත් අනුපාතය තියුණු ලෙස අඩු වීම හා ඉන්දියාවේ තරුණ ජනගහන ගම්‍යතාව (Population Momentum)", "චීනයේ මුළු ජනගහනයම සංක්‍රමණය වීම", "ඉන්දියාවේ භූමි ප්‍රමාණය දෙගුණ වීම", "චීනයේ කෘෂිකර්මය නතර වීම",
        "තරුණ පරපුර විශාල වීම නිසා සාඵල්‍යතා අනුපාතය අඩු වුවද තවත් දශක කිහිපයක් ජනගහනය වැඩි වීම 'ජනගහන ගම්‍යතාව' නම් වේ."),
      q(t, "මානව ජනාවාස භූගෝල විද්‍යාවේදී ජනාවාසයක් පිහිටුවීමේ 'ස්ථානය' (Site) සහ 'පිහිටුම් පරිසරය/සම්බන්ධතාව' (Situation) අතර වෙනස කුමක්ද?",
        "Site යනු ජනාවාසය ඉදි කළ භෞතික භූමි ස්වභාවය (උස, ජලය, පස) වන අතර Situation යනු අවට නගර, මාර්ග හා වෙළඳ මධ්‍යස්ථානවලට ඇති සාපේක්ෂ පිහිටීමයි", "දෙකම එකම දෙයකි", "Site යනු ජනගහනයයි", "Situation යනු වර්ෂාපතනයයි",
        "සිංගප්පූරුව කුඩා දූපතක් වුවද (Site), මලක්කා සමුද්‍ර සන්ධියේ (Situation) පිහිටීම එහි දියුණුවට හේතු විය."),
      q(t, "නිවාස එකිනෙකට ඉතා සමීපව ගොනු වී පිහිටි ජනාවාස රටාව හඳුන්වනු ලබන්නේ කුමන නමින්ද?",
        "ගොනු වූ / කේන්ද්‍රගත ජනාවාස (Nucleated / Clustered Settlement)", "විසිරුණු ජනාවාස", "රේඛීය ජනාවාස", "අර්ධ කවාකාර ජනාවාස",
        "ජල මූලාශ්‍රයක් (වැවක්), පොදු ආරක්ෂාවක් හෝ සාරවත් ගොවි බිම් මධ්‍යයේ ගොනු වූ ජනාවාස බහුලව බිහිවේ."),
      q(t, "මහාමාර්ගයක්, ගංගා ඉවුරක්, ඇළක් හෝ වෙරළ තීරයක් දිගේ දිගට විහිදී ඇති ජනාවාස රටාව කුමක්ද?",
        "රේඛීය ජනාවාස (Linear Settlement)", "ගොනු වූ ජනාවාස", "විසිරුණු ජනාවාස", "වෘත්තාකාර ජනාවාස",
        "ප්‍රවාහන පහසුව හා ජල පහසුව ලබා ගැනීමට මිනිසුන් මාර්ග හා ගංගා දෙපස නිවාස ඉදිකරන විට රේඛීය රටාව ඇතිවේ."),
      q(t, "විශාල කඳුකර ප්‍රදේශවල, වතුයායවල හෝ අර්ධ ශුෂ්ක ගොවිපළවල නිවාස එකිනෙකින් බොහෝ දුරින් පිහිටන ජනාවාස රටාව කුමක්ද?",
        "විසිරුණු ජනාවාස (Dispersed / Scattered Settlement)", "රේඛීය ජනාවාස", "ගොනු වූ ජනාවාස", "තාරකා ජනාවාස",
        "විශාල තනි ගොවිපළවල් පවතින පෙදෙස්වල (උදා: කැනඩාවේ ප්‍රේරි තණබිම් හෝ උස් කඳු බෑවුම්) විසිරුණු ජනාවාස දක්නට ලැබේ."),
      q(t, "ග්‍රාමීය ජනාවාසයක් සහ නාගරික ජනාවාසයක් අතර ඇති ප්‍රධාන ආර්ථික වෙනස කුමක්ද?",
        "ග්‍රාමීය ජනාවාස ප්‍රධාන වශයෙන් කෘෂිකර්මය, ධීවර හා වන වගාව වැනි ප්‍රාථමික අංශ මත රඳා පවතින අතර නාගරික ජනාවාස ද්විතීයික හා තෘතීයික සේවා අංශ මත රඳා පවතී", "නගරයේ ගොවිතැන් පමණක් සිදු වේ", "ගමේ කර්මාන්තශාලා පමණක් ඇත", "කිසිදු වෙනසක් නැත",
        "එමෙන්ම නගරවල ජන ඝනත්වය හා ගොඩනැගිලි ඝනත්වය ගමට වඩා බෙහෙවින් වැඩිය."),
      q(t, "'නාගරීකරණය' (Urbanization) යනුවෙන් අර්ථ දක්වන්නේ කුමක්ද?",
        "රටක හෝ කලාපයක මුළු ජනගහනයෙන් නාගරික ප්‍රදේශවල ජීවත් වන ජනගහන ප්‍රතිශතය ඉහළ යාමේ ක්‍රියාවලිය", "නගරවල ගස් වැවීම", "ග්‍රාමීය ජනගහනය වැඩිවීම", "නගර කඩා බිඳ දැමීම",
        "1950 දී ලෝක ජනගහනයෙන් ~30% ක් නාගරික වූ අතර වර්තමානයේ එය 56% කට වඩා ඉහළ ගොස් ඇත."),
      q(t, "ජනගහනය මිලියන 10 කට (කෝටියකට) වඩා වැඩි නගරයක් භූගෝල විද්‍යාවේ හඳුන්වනු ලබන්නේ කුමන නමින්ද?",
        "මෙගා නගරය (Megacity)", "කුඩා නගරය (Town)", "ග්‍රාමීය මධ්‍යස්ථානය", "වෙළඳ ගම්මානය",
        "ටෝකියෝ, දිල්ලි, ෂැංහයි, සාඕ පාවුලෝ, මෙක්සිකෝ සිටි හා කයිරෝ ලොව ප්‍රධාන මෙගා නගර අතර වේ."),
      q(t, "'ප්‍රමුඛ නගරය' (Primate City) යන සංකල්පය (Mark Jefferson) පැහැදිලි කරන්නේ කුමක්ද?",
        "රටේ දෙවන විශාලතම නගරය මෙන් දෙගුණයකටත් වඩා විශාල, ආර්ථික හා දේශපාලන බලය අධික ලෙස ඒකරාශී වූ රටේ ප්‍රධානතම නගරය", "රටේ කුඩාම නගරය", "ගොවි ගම්මානය", "දේශසීමා මුරපොළ",
        "බැංකොක් (තායිලන්තය), ලන්ඩන් හෝ පැරිස් ප්‍රමුඛ නගර සඳහා සම්භාව්‍ය උදාහරණ වේ."),
      q(t, "'බර්ජස්ගේ ඒක කේන්ද්‍රීය කලාප ආකෘතිය' (Burgess Concentric Zone Model - 1925) අනුව නගරයක මධ්‍යයේම පිහිටා ඇති කලාපය කුමක්ද?",
        "මධ්‍යම ව්‍යාපාරික දිස්ත්‍රික්කය (Central Business District - CBD)", "බැහැර ගොවිපළ කලාපය", "ඉහළ ආදායම් නේවාසික කලාපය", "වනාන්තර රක්ෂිතය",
        "CBD ප්‍රදේශයේ බැංකු, ප්‍රධාන කාර්යාල, වෙළඳ සංකීර්ණ සහ ප්‍රවාහන මධ්‍යස්ථාන පිහිටන අතර ඉඩම් වටිනාකම උපරිම වේ."),
      q(t, "නගරයක මධ්‍යම ව්‍යාපාරික දිස්ත්‍රික්කයේ (CBD) අහස උසට නැගුණු ගොඩනැගිලි (Skyscrapers) ඉදි වීමට ප්‍රධාන ආර්ථික හේතුව කුමක්ද?",
        "ඉඩම් ඉල්ලුම අධික වීම හා ඉඩම් මිල ඉතා ඉහළ වීම නිසා සීමිත බිම් ප්‍රමාණයකින් උපරිම මහල් ප්‍රමාණයක් ලබා ගැනීම", "සුළඟින් බේරීමට", "වැසි ජලය එකතු කිරීමට", "භූමිකම්පා වැඩි කිරීමට",
        "මෙය 'ලංසු කුලී න්‍යාය' (Bid-Rent Theory) මගින් පැහැදිලි කෙරේ."),
      q(t, "සංවර්ධනය වෙමින් පවතින රටවල විශාල නගරවල (මුම්බායි, රියෝ ද ජැනයිරෝ, නයිරෝබි) දක්නට ලැබෙන 'පැල්පත් හා අනවසර ජනාවාස' (Slums / Shanty Towns) බිහිවීමට ප්‍රධාන හේතුව කුමක්ද?",
        "වේගවත් ග්‍රාමීය-නාගරික සංක්‍රමණයට සරිලන පරිදි දැරිය හැකි නිවාස, රැකියා හා යටිතල පහසුකම් නගරය තුළ සැපයීමට නොහැකි වීම", "ඉඩම් මිල ඉතා අඩු වීම", "නගරවල ජනගහනය අඩු වීම", "වන සතුන්ගෙන් බේරීමට",
        "මෙවැනි ජනාවාසවල පිරිසිදු පානීය ජලය, සනීපාරක්ෂාව හා ගංවතුර ආරක්ෂාව අවම මට්ටමක පවතී."),
      q(t, "'නාගරික තාප දූපත' (Urban Heat Island - UHI) යනු නගරාශ්‍රිතව ඇතිවන කුමන පාරිසරික සංසිද්ධියද?",
        "කොන්ක්‍රීට්, තාර, වාහන දුම සහ වෘක්ෂලතා අඩුවීම නිසා නගර මධ්‍යයේ උෂ්ණත්වය අවට ග්‍රාමීය පෙදෙස්වලට වඩා සැලකිය යුතු ලෙස ඉහළ යාම", "නගරය වටා මුහුද තිබීම", "නගරයට පමණක් හිම වැටීම", "ග්‍රාමීය පෙදෙස් නගරයට වඩා උණුසුම් වීම",
        "නාගරික හරිත උද්‍යාන, වහල මත වගාවන් (Green Roofs) හා ජල මූලාශ්‍ර මගින් මෙම තාප බලපෑම අවම කළ හැකිය."),
      q(t, "'තදාසන්නකරණය' (Suburbanization) සහ 'නාගරික පැතිරීම' (Urban Sprawl) නිසා ඇතිවන ප්‍රධාන පාරිසරික හා ප්‍රවාහන ගැටලුව කුමක්ද?",
        "අවට කෘෂිකාර්මික හා වනාන්තර ඉඩම් විනාශ වීම, මාර්ග තදබදය ඉහළ යාම සහ පොදු පහසුකම් සැපයීමේ පිරිවැය වැඩි වීම", "නගරයේ ජනගහනය වැඩිවීම නැවතීම", "පානීය ජලය වැඩි වීම", "මාර්ග අවශ්‍ය නොවීම",
        "සැලසුම් රහිතව අඩු ඝනත්වයකින් නගරය පිටතට පැතිරීම තිරසාර නොවන බව නාගරික සැලසුම්කරුවන් පෙන්වා දෙයි."),
      q(t, "'ප්‍රති-නාගරීකරණය' (Counter-urbanization) යන්නෙන් විස්තර කෙරෙන්නේ කුමන ක්‍රියාවලියද?",
        "මහා නගරවල තදබදය, දූෂණය හා ඉහළ ජීවන වියදම නිසා ජනතාව නගර හැර ග්‍රාමීය හෝ කුඩා නගර වෙත පදිංචියට යාම", "ගමේ සිට නගරයට පැමිණීම", "රටින් පිටව යාම", "ගම්මාන නගර බවට පත් කිරීම",
        "අන්තර්ජාලය හා දුරස්ථ රැකියා (Remote Work) පහසුකම් නිසා සංවර්ධිත රටවල මෙම ප්‍රවණතාව දක්නට ලැබේ."),
      q(t, "'ප්‍රතිජීවනය / ජෙන්ට්‍රිෆිකේෂන්' (Gentrification) නාගරික ක්‍රියාවලිය තුළ සිදුවන්නේ කුමක්ද?",
        "පැරණි, පරිහානියට පත් නාගරික කොටසක් නවීකරණය කර ධනවත් පිරිස් පදිංචි වීමත් සමඟ දේපළ මිල ඉහළ ගොස් මුල් අඩු ආදායම්ලාභී පදිංචිකරුවන් ඉවත් වීමට සිදුවීම", "නගරය කෘෂිකාර්මික බිමක් කිරීම", "සියලු ගොඩනැගිලි කඩා දැමීම", "නගරයේ රැකියා නැති වීම",
        "මෙය නගරයේ භෞතික පෙනුම හා බදු ආදායම වැඩි කළද සමාජ අසමානතා හා නිවාස අහිමි වීම් ඇති කළ හැකිය."),
      q(t, "වෝල්ටර් ක්‍රිස්ටලර්ගේ (Walter Christaller) 'මධ්‍යස්ථාන න්‍යාය' (Central Place Theory - 1933) පදනම් වී ඇත්තේ කුමක් පැහැදිලි කිරීමටද?",
        "සේවා සපයන ජනාවාස (ගම්, කුඩා නගර, විශාල නගර) ප්‍රමාණය, ගණන හා ඒවා අතර භූගෝලීය දුරස්ථභාවය ෂඩාස්‍රාකාර (Hexagonal) ජාලයකින් සැකසෙන ආකාරය", "ගිනිකඳු පිපිරෙන ආකාරය", "සුළං හමන දිශාව", "ගංගා ගලා යන ආකාරය",
        "විශාල සේවා මධ්‍යස්ථාන (රෝහල්, විශ්වවිද්‍යාල) ස්වල්පයක් විශාල වෙළඳපොළ පරාසයක් ආවරණය කරන අතර කුඩා සේවා මධ්‍යස්ථාන බහුලව ඇත."),
      q(t, "ජනාවාස ධුරාවලියේදී (Settlement Hierarchy) 'දිසාපතිවරයෙකු හෝ නගර දෙකක් හමුවන මහා සමූහ නගරය' (Conurbation) යනු කුමක්ද?",
        "ප්‍රසාරණය වෙමින් එකිනෙකට යා වී පොදු නාගරික කලාපයක් සාදන නගර කිහිපයක එකතුවකි (උදා: මහා ටෝකියෝ, ලන්ඩන්, රුර් කලාපය)", "හුදකලා කඳුකර ගම්මානයකි", "වැවක් වටා ඇති ගමකි", "ධීවර වරායකි",
        "අතිවිශාල නගර කලාප කිහිපයක් මෙලෙස යා වීමෙන් ඇතිවන මහා තීරුව 'මෙගලෝපොලිස්' (Megalopolis - උදා: බොස්වොෂ්) ලෙස හැඳින්වේ."),
      q(t, "ජනගහන ප්‍රතිපත්ති අතර චීනය 1979–2015 කාලයේ ක්‍රියාත්මක කළ 'එක් දරු ප්‍රතිපත්තිය' කුමන වර්ගයේ ප්‍රතිපත්තියක්ද?",
        "ජනගහන වර්ධනය පාලනය කිරීමේ 'උපත් විරෝධී' (Anti-natalist) ප්‍රතිපත්තියක්", "උපත් දිරිමත් කිරීමේ (Pro-natalist) ප්‍රතිපත්තියක්", "නාගරික සංක්‍රමණ ප්‍රතිපත්තියක්", "ආහාර ආනයන ප්‍රතිපත්තියක්",
        "ඊට ප්‍රතිවිරුද්ධව උපත් අඩු ප්‍රංශය, සිංගප්පූරුව හා ජපානය දරු ප්‍රසූති දිරිමත් කරන Pro-natalist ප්‍රතිපත්ති ක්‍රියාත්මක කරයි."),
      q(t, "ලොව ජනගහනය වේගයෙන් වයස්ගත වන රටවල් ශ්‍රම හිඟය පියවා ගැනීමට ගන්නා ප්‍රධාන ප්‍රතිපත්තිමය පියවර මොනවාද?",
        "විශ්‍රාම යන වයස ඉහළ දැමීම, ස්වයංක්‍රීයකරණය/රොබෝ තාක්ෂණය භාවිතය සහ පුහුණු විදේශීය සංක්‍රමණිකයන් ආකර්ෂණය කර ගැනීම", "පාසල් වසා දැමීම", "රෝහල් අඩු කිරීම", "කෘෂිකර්මය තහනම් කිරීම",
        "කැනඩාව, ජර්මනිය සහ ඔස්ට්‍රේලියාව කුසලතා පදනම් කරගත් සංක්‍රමණ ක්‍රම මගින් ශ්‍රම බලකාය පවත්වා ගනී."),
      q(t, "ශ්‍රී ලංකාවේ ජනගහන ව්‍යාප්තිය සලකන විට, වර්ග කිලෝමීටරයට ඉහළම ජන ඝනත්වය (පුද්ගලයන් 3,400+ පමණ) වාර්තා වන දිස්ත්‍රික්කය කුමක්ද?",
        "කොළඹ දිස්ත්‍රික්කය (ඉන්පසු ගම්පහ දිස්ත්‍රික්කය)", "මුලතිව් දිස්ත්‍රික්කය", "මොණරාගල දිස්ත්‍රික්කය", "වවුනියාව දිස්ත්‍රික්කය",
        "ශ්‍රී ලංකාවේ බස්නාහිර පළාතේ පමණක් රටේ මුළු ජනගහනයෙන් හතරෙන් පංගුවකට වඩා ජීවත් වේ."),
      q(t, "ශ්‍රී ලංකාවේ අඩුම ජන ඝනත්වයක් දක්නට ලැබෙන දිස්ත්‍රික්ක අතරට අයත් වන්නේ කුමන දිස්ත්‍රික්කද?",
        "මුලතිව්, මන්නාරම, වවුනියාව සහ මොණරාගල දිස්ත්‍රික්ක", "කොළඹ සහ ගම්පහ", "කළුතර සහ ගාල්ල", "මහනුවර සහ මාතර",
        "මුලතිව් දිස්ත්‍රික්කයේ විශාල වන රක්ෂිත පැවතීම හා ඓතිහාසික සාධක නිසා ජන ඝනත්වය වර්ග කි.මී. ට 40–50 පමණ අවම අගයක පවතී."),
      q(t, "ශ්‍රී ලංකාවේ සමස්ත ජනගහනයෙන් වැඩිම පිරිසක් ජීවත් වන 'ජනාවාස අංශය' (Sector) කුමක්ද?",
        "ග්‍රාමීය අංශය (Rural Sector - ආසන්න වශයෙන් 77% ක් පමණ)", "නාගරික අංශය (90%)", "වතු අංශය (60%)", "ධීවර අංශය (50%)",
        "ශ්‍රී ලංකාවේ නාගරික අංශයේ ~18% ක් ද වතු අංශයේ ~4.4% ක් ද වාසය කරන අතර අර්ධ-නාගරික පෙදෙස් බහුලය."),
      q(t, "ශ්‍රී ලංකාවේ 'වතු ජනාවාස' (Estate Settlements) වලට ආවේණික භූගෝලීය පිහිටීම හා ව්‍යුහය කෙබඳුද?",
        "මධ්‍යම කඳුකරයේ හා තෙත් කලාපීය තේ/රබර් වතු ඇතුළත පිහිටි ලයිම් කාමර පේළි හා නවීන තනි නිවාස ගම්මාන", "වියළි කලාපයේ වැව් බැඳි ගම්මාන", "උතුරේ කොරල් දූපත්", "වෙරළබඩ ධීවර තොටුපළවල්",
        "මෙම ජනාවාසවල පානීය ජලය, සෞඛ්‍ය හා ප්‍රවාහන යටිතල පහසුකම් වැඩිදියුණු කිරීම කෙරෙහි අවධානය යොමු කෙරේ."),
      q(t, "ශ්‍රී ලංකාවේ වියළි කලාපයේ පුරාණ ග්‍රාමීය ජනාවාසයක් වන 'ගම්ගොඩ - වැව - කුඹුර' යන ත්‍රිත්ව සැකැස්මේ පිහිටීම කුමක්ද?",
        "වැව් බැම්මට පහළින් ජල පාලනය යටතේ කුඹුරු යායත්, ඊට ඉහළ උස් බිමේ ගංවතුරෙන් ආරක්ෂිතව නිවාස (ගම්ගොඩ) සහ වගා බිමත් පිහිටීම", "වැව ඇතුළත නිවාස ඉදිකිරීම", "කඳු මුදුනේ කුඹුරු කිරීම", "මුහුද අසල වැව බැඳීම",
        "මෙම සාම්ප්‍රදායික පාරිසරික සැලැස්ම මගින් ජලය, පස හා සෞඛ්‍යාරක්ෂාව සුරැකිණි."),
      q(t, "'ස්මාර්ට් නගර' (Smart Cities) සංකල්පයේ ප්‍රධාන අරමුණ කුමක්ද?",
        "තොරතුරු තාක්ෂණය, සංවේදක ජාල හා හරිත බලශක්තිය යොදා ගනිමින් ප්‍රවාහනය, ජලය, කසළ හා බලශක්තිය කාර්යක්ෂමව කළමනාකරණය කර ජීවන තත්ත්වය ඉහළ නැංවීම", "නගරයේ සියලු ගස් කැපීම", "පොදු ප්‍රවාහනය නතර කිරීම", "කඩදාසි ලිපි පමණක් භාවිතය",
        "සිංගප්පූරුව, සෝල්, බාසිලෝනා හා ආම්ස්ටර්ඩෑම් ප්‍රමුඛ ස්මාර්ට් නගර සඳහා උදාහරණ වේ."),
      q(t, "එක්සත් ජාතීන්ගේ තිරසාර සංවර්ධන ඉලක්ක අතර 'SDG 11' මගින් අවධාරණය කරන්නේ කුමක්ද?",
        "නගර සහ මානව ජනාවාස අන්තර්ග්‍රහණය කරන, ආරක්ෂිත, ඔරොත්තු දෙන සහ තිරසාර බවට පත් කිරීම", "මුහුදු මට්ටම ඉහළ දැමීම", "සියලු ගම් නගර කිරීම", "වනාන්තර ඉවත් කිරීම",
        "තිරසාර නාගරික සැලසුම්කරණය සඳහා පොදු ප්‍රවාහනය, හරිත අවකාශයන් හා ආරක්ෂිත නිවාස අත්‍යවශ්‍ය වේ."),
      q(t, "ජනගහන සංගණනයක් (Population Census) සාමාන්‍යයෙන් වසර කීයකට වරක් පැවැත්වෙන කාර්යයක්ද? (ශ්‍රී ලංකාව ඇතුළු බොහෝ රටවල)",
        "සෑම වසර 10 කට වරක්", "සෑම මසකට වරක්", "සෑම වසර 100 කට වරක්", "සෑම සතියකට වරක්",
        "ජාතික සැලසුම්, මැතිවරණ කොට්ඨාස, පාසල් හා රෝහල් අවශ්‍යතා තීරණය කිරීමට ජන සංගණන දත්ත අත්‍යවශ්‍ය වේ."),
      q(t, "'ඩි ෆැක්ටෝ' (De Facto) ජන සංගණන ක්‍රමයේදී පුද්ගලයෙකු ගණන් ගනු ලබන්නේ කුමන පදනම මතද?",
        "සංගණන රාත්‍රියේදී ඔහු හෝ ඇය භෞතිකව සිටින ස්ථානය අනුව", "ඔහු උපන් නගරය අනුව", "ඔහුගේ රැකියා ස්ථානය අනුව", "ඔහුගේ පාසල අනුව",
        "ඊට වෙනස්ව 'ඩි ජූර්' (De Jure) ක්‍රමයේදී පුද්ගලයාගේ සාමාන්‍ය/නීත්‍යානුකූල පදිංචි ස්ථානය අනුව ගණන් ගැනේ."),
      q(t, "ජනගහන පුරෝකථනයේදී 'ස්වාභාවික වර්ධනයට' අමතරව අනිවාර්යයෙන්ම සැලකිල්ලට ගත යුතු අනෙක් සංරචකය කුමක්ද?",
        "ශුද්ධ සංක්‍රමණය (Net Migration = ආගමනය − විගමනය)", "වර්ෂාපතනය", "මෝසම් සුළං", "ඛනිජ සංචිත",
        "ජනගහන වෙනස්වීම = (උපත් − මරණ) + (ආගමන − විගමන) යන ජන විකාශන සමීකරණයෙන් ගණනය කෙරේ."),
      q(t, "විදේශයක සිට තම මව් රටට පැමිණීම 'ආගමනය' (Immigration) වන අතර තම රටෙන් පිටවී වෙනත් රටක පදිංචියට යාම හඳුන්වන්නේ කුමන නමින්ද?",
        "විගමනය (Emigration)", "නාගරීකරණය", "විසරණය", "සංකේන්ද්‍රණය",
        "ආගමන සංඛ්‍යාව විගමන සංඛ්‍යාවට වඩා වැඩි නම් ශුද්ධ සංක්‍රමණය ධන අගයක් ගනී."),
      q(t, "'අනිවාර්ය / බලහත්කාර සංක්‍රමණය' (Forced Migration) සඳහා ඓතිහාසික මෙන්ම වර්තමාන උදාහරණයක් වන්නේ කුමක්ද?",
        "යුද්ධ, ජනවාර්ගික පීඩන, වහල් වෙළඳාම හෝ මහා ජලාශ/ආපදා නිසා ජනතාවට බලහත්කාරයෙන් පදිංචිය අතහැරීමට සිදුවීම", "උසස් අධ්‍යාපනය සඳහා විදේශගත වීම", "විනෝද සංචාර", "විශ්‍රාම ගැනීමෙන් පසු වෙරළට යාම",
        "සිය කැමැත්තෙන් රැකියා හෝ අධ්‍යාපනය සඳහා යාම 'ස්වේච්ඡා සංක්‍රමණය' (Voluntary Migration) නම් වේ."),
      q(t, "'හොයිට්ගේ කලාප ආකෘතිය' (Hoyt Sector Model - 1939) බර්ජස්ගේ ඒක කේන්ද්‍රීය ආකෘතියට වඩා වෙනස් වන්නේ කෙසේද?",
        "නගරයේ ඉඩම් පරිභෝජනය ඒක කේන්ද්‍රීය වළලු ලෙස නොව, මධ්‍යම ව්‍යාපාරික දිස්ත්‍රික්කයේ (CBD) සිට මහාමාර්ග හා දුම්රිය මාර්ග ඔස්සේ කූඤ්ඤ හැඩැති කලාප (Wedges/Sectors) ලෙස විහිදෙන බව පෙන්වයි", "සියලු නගර වෘත්තාකාර බව පෙන්වයි", "නගරය ගඟක් මැද පිහිටන බව පෙන්වයි", "කර්මාන්ත නගර මධ්‍යයේම පිහිටන බව පෙන්වයි",
        "ප්‍රවාහන මාර්ග දිගේ කර්මාන්ත හා විවිධ ආදායම් මට්ටම්වල නේවාසික කලාප පිටතට විහිදෙන ආකාරය හොමර් හොයිට් පැහැදිලි කළේය."),
      q(t, "හැරිස් සහ උල්මන්ගේ 'බහු-න්‍යෂ්ටික ආකෘතිය' (Multiple Nuclei Model - 1945) අනුව නූතන මහා නගරයක් වර්ධනය වන්නේ කෙසේද?",
        "තනි මධ්‍යස්ථානයක් වටා පමණක් නොව ගුවන්තොටුපළ, විශ්වවිද්‍යාල, වරාය හා තදාසන්න ව්‍යාපාර උද්‍යාන වැනි විශේෂිත කේන්ද්‍ර කිහිපයක් (Multiple Nuclei) වටා වර්ධනය වීම", "එකම වීදියක් දිගේ පමණි", "ගොවිපළවල් මැද පමණි", "කිසිදු මධ්‍යස්ථානයක් නැතිවය",
        "නූතන නගරවල වාණිජ, අධ්‍යාපනික හා කාර්මික ක්‍රියාකාරකම් සඳහා විවිධ උප-මධ්‍යස්ථාන බිහි වේ."),
      q(t, "නාගරික භූගෝල විද්‍යාවේ 'ලංසු කුලී න්‍යාය' (Bid-Rent Theory) අනුව නගර මධ්‍යයේ (CBD) සිට දුර වැඩි වන විට සිදුවන්නේ කුමක්ද?",
        "ඉඩම් කුලිය සහ ගොඩනැගිලි ඝනත්වය ක්‍රමයෙන් අඩු වන අතර සිල්ලර වෙළඳාම, කාර්යාල, කර්මාන්ත හා නිවාස ලෙස ඉඩම් පරිභෝජනය වෙනස් වේ", "ඉඩම් මිල අනන්තයට ඉහළ යයි", "මහල් නිවාස උසින් වැඩි වේ", "ගොවිතැන නගර මධ්‍යයට පැමිණේ",
        "ගනුදෙනුකරුවන් හා ප්‍රවේශ්‍යතාව වැඩිම නගර මධ්‍යය සඳහා සිල්ලර වෙළඳ ආයතන හා බැංකු වැඩිම කුලිය ගෙවීමට සූදානම් වේ."),
      q(t, "එවරට් ලීගේ (Everett Lee - 1966) සංක්‍රමණ ආකෘතියේ 'අතරමැදි බාධක' (Intervening Obstacles) ලෙස හඳුන්වන්නේ මොනවාද?",
        "ගමන් දුර, සංක්‍රමණ පිරිවැය, දේශසීමා/වීසා නීති, සාගර හෝ කඳු වැනි භෞතික බාධක සහ භාෂා වෙනස්කම්", "ආකර්ෂණීය වැටුප්", "හොඳ පාසල්", "සාමකාමී පරිසරය",
        "මිනිසුන්ට ගමනාන්තයකට යාමට ඇති තල්ලු හා ඇදගැනීමේ සාධක අතර මෙම බාධක ජය ගැනීමට සිදුවේ."),
      q(t, "ගුරුත්වාකර්ෂණ සංක්‍රමණ ආකෘතිය (Gravity Model of Migration) අනුව ස්ථාන දෙකක් අතර සංක්‍රමණිකයන් හෝ වෙළඳ ගමනාගමනය වැඩි වන්නේ කුමන තත්ත්ව යටතේද?",
        "ස්ථාන දෙකේ ජනගහන ප්‍රමාණය විශාල වන තරමට සහ ඒවා අතර භූගෝලීය දුර අඩු වන තරමට", "දුර වැඩි වන තරමට", "ජනගහනය ශුන්‍ය වන තරමට", "මුහුදු මට්ටම ඉහළ යන තරමට",
        "නිව්ටන්ගේ ගුරුත්වාකර්ෂණ නියමය ආශ්‍රයෙන් සැකසුණු මෙම ආකෘතිය නාගරික අන්තර්ක්‍රියා පුරෝකථනය කිරීමට යොදා ගනී."),
      q(t, "'හරිත තීරය' (Green Belt) යන නාගරික සැලසුම් උපායමාර්ගය ක්‍රියාත්මක කිරීමේ ප්‍රධාන අරමුණ කුමක්ද?",
        "විශාල නගරයක් වටා ගොඩනැගිලි ඉදිකිරීම සීමා කළ ස්වාභාවික වනාන්තර හා කෘෂිකාර්මික වළල්ලක් තබා පාලනයකින් තොර නාගරික පැතිරීම (Urban Sprawl) වැළැක්වීම", "සියලු ගස් කපා කර්මාන්ත ඉදිකිරීම", "නගරය වටා තාප්පයක් බැඳීම", "වැව් ගොඩකිරීම",
        "ලන්ඩන් හා ඔටාවා වැනි නගර වටා නාගරික ව්‍යාප්තිය පාලනය කිරීමට හරිත තීර ප්‍රතිපත්තිය සාර්ථකව යොදා ගෙන ඇත."),
      q(t, "'දුඹුරු බිම් සංවර්ධනය' (Brownfield Development) යන්න 'හරිත බිම් සංවර්ධනයට' (Greenfield Development) වඩා පරිසර හිතකාමී වන්නේ ඇයි?",
        "අලුතින් ස්වාභාවික වනාන්තර හෝ කෘෂිකාර්මික ඉඩම් (Greenfield) විනාශ නොකර, නගරය තුළ අතහැර දමා ඇති පැරණි කාර්මික හෝ දුම්රිය භූමි පිරිසිදු කර නැවත සංවර්ධනය කරන බැවින්", "කොළ පැහැති ගොඩනැගිලි තැනීම නිසා", "කාන්තාරවල ගෙවල් තැනීම නිසා", "ගංගා ඉවුරු ගොඩකිරීම නිසා",
        "දුඹුරු බිම් ප්‍රතිසංවර්ධනය නගර මධ්‍යය පණ ගන්වමින් නාගරික පැතිරීම අවම කරයි."),
      q(t, "'ළමා අනුපාතයට වඩා වැඩිහිටි අනුපාතය' ඉහළ යන ජපානයේ වර්තමාන ජනගහන සංසිද්ධියට ආසන්නතම සමාජීය හේතු මොනවාද?",
        "විවාහ වන වයස පමා වීම, ඉහළ රැකියා හා ජීවන පිරිවැය නිසා අඩු දරු උපත් හා ඉතා ඉහළ ආයු අපේක්ෂාව (~අවුරුදු 84+)", "වසංගත රෝග පැතිරීම", "කෘෂිකර්මය පමණක් පැවතීම", "ළමුන් විදේශගත කිරීම",
        "ජපානයේ 'සුපිරි වයස්ගත සමාජය' (Super-aged Society) තුළ ජනගහනයෙන් 29% කට වඩා වයස 65 ඉක්මවූවන් වේ."),
      q(t, "'ස්ත්‍රී පුරුෂ සමානාත්මතාවය සහ කාන්තා අධ්‍යාපනය' ජනගහන වර්ධන වේගය මත සෘජුවම ඇති කරන බලපෑම කුමක්ද?",
        "කාන්තාවන් උසස් අධ්‍යාපනය හා රැකියාවලට යොමු වීමත් සමඟ විවාහ වන වයස ඉහළ ගොස් සාඵල්‍යතා අනුපාතය (TFR) ස්වාභාවිකව පහත වැටීම", "උපත් අනුපාතය දෙගුණ වීම", "ළදරු මරණ වැඩි වීම", "කිසිදු බලපෑමක් නැති වීම",
        "කේරළය හා ශ්‍රී ලංකාව කාන්තා සාක්ෂරතාවය ඉහළ නැංවීමෙන් ඉක්මනින් අඩු උපත් අනුපාතයකට ළඟා වූ හොඳම උදාහරණ වේ."),
      q(t, "ජනාවාසයක් සැලසුම් කිරීමේදී 'තෙත් කරල් ස්ථානය' (Wet-Point Site) ලෙස හැඳින්වෙන්නේ කුමන ආකාරයේ ජනාවාස පිහිටීමක්ද?",
        "වියළි හෝ හුණුගල් ප්‍රදේශයක උල්පතක්, ක්ෂේම භූමියක් හෝ ගංගාවක් වැනි ජල මූලාශ්‍රයක් අසල පිහිටුවන ජනාවාසය", "ගංවතුරට යටවන ස්ථානයකි", "සාගරය මැද පිහිටි නැවකි", "කඳු මුදුනක හිම ගොඩකි",
        "ඊට ප්‍රතිවිරුද්ධව ගංවතුර හා වගුරු බිම්වලින් බේරී උස් ගොඩැල්ලක පිහිටුවන ජනාවාස 'වියළි ස්ථානය' (Dry-Point Site) නම් වේ."),
      q(t, "'ආරක්ෂක ස්ථාන' (Defensive Sites) මත පුරාණයේදී ගොඩනැගුණු ජනාවාසවලට භූගෝලීය උදාහරණ කවරේද?",
        "සීගිරිය, ඇතැන්ස්හි ඇක්‍රොපොලිස්, එඩින්බරෝ සහ ගංගා වංගු (Meander Loops) තුළ පිහිටි ඩර්හැම් වැනි නගර", "සාගර පතුලේ නගර", "නිම්න මධ්‍යයේ විවෘත නගර", "මුහුදු වෙරළේ වැලි කඳු",
        "සතුරු ආක්‍රමණවලින් ආරක්ෂා වීමට උස් පර්වත හෝ ගංගාවකින් තුන් පැත්තක් වටවූ ස්ථාන තෝරා ගැනිණි."),
      q(t, "'තොටුපළ හා පාලම් ස්ථාන' (Bridging-Point Sites) ලෙස ආරම්භ වී පසුව මහා නගර බවට පත්වූ නගර මොනවාද?",
        "ලන්ඩන් (තේම්ස් ගඟ හරහා), පැරිස් (සේන් ගඟ හරහා) සහ කැලණිය/පේරාදෙණිය වැනි ගංගා හරස් කරන ස්ථාන", "සහරා කාන්තාර නගර", "ඇන්ටාක්ටික් කඳවුරු", "එවරස්ට් කඳු මුදුන",
        "ගඟක් පටු වන හෝ ගොඩ වී තරණය කළ හැකි ස්ථානයක වෙළඳ මාර්ග හමුවීම නිසා ජනාවාස දියුණු වේ."),
      q(t, "ජනගහනයේ 'සක්‍රීය ශ්‍රම බලකාය' (Economically Active Population) ලෙස ජාත්‍යන්තරව ගණන් ගනු ලබන්නේ කුමන වයස් කාණ්ඩයද?",
        "වයස අවුරුදු 15 සිට 64 දක්වා වූ වැඩ කිරීමට සුදුසු හා සූදානම් ජනගහනය", "වයස අවුරුදු 0–14 පිරිස", "වයස අවුරුදු 70 ට වැඩි පිරිස", "වයස අවුරුදු 5–10 පිරිස",
        "යැපුම් ජනගහනයේ බර දරා ආර්ථික නිෂ්පාදනය සිදු කරනු ලබන්නේ මෙම වයස් කාණ්ඩය විසිනි."),
      q(t, "'සංක්‍රමණිකයන් විසින් මව් රටට එවන මුදල්' (Remittances) සංවර්ධනය වෙමින් පවතින රටවලට ආර්ථික වශයෙන් වැදගත් වන්නේ ඇයි?",
        "රටට විදේශ විනිමය සෘජුවම ලැබීම, පවුල් ආදායම හා අධ්‍යාපන/සෞඛ්‍ය වියදම් ඉහළ යාම සහ දිළිඳුකම අඩුවීම", "වනාන්තර කැපීම වැඩි කිරීමට", "ආනයන නතර කිරීමට", "ජනගහනය අඩු කිරීමට පමණි",
        "ශ්‍රී ලංකාව, පිලිපීනය, නේපාලය හා ඉන්දියාව වැනි රටවල විදේශ සේවා නියුක්තිකයන්ගේ ප්‍රේෂණ ප්‍රධාන ආදායම් මාර්ගයකි."),
      q(t, "නාගරික රැකියා ව්‍යුහයේ 'අවිධිමත් අංශය' (Informal Sector) යන්නෙන් අදහස් කරන්නේ කුමන ආර්ථික ක්‍රියාකාරකම්ද?",
        "වීදි වෙළඳාම, දෛනික කුලී වැඩ, ත්‍රිරෝද රථ සේවා හා කුඩා පරිමාණ ගෘහ කර්මාන්ත වැනි රජයේ ලියාපදිංචිය, ස්ථිර වැටුප් හෝ සමාජ ආරක්ෂණය අඩු රැකියා", "මහ බැංකු රැකියා", "බහුජාතික සමාගම් විධායක රැකියා", "විශ්වවිද්‍යාල මහාචාර්ය ධුර",
        "සංවර්ධනය වෙමින් පවතින රටවල නාගරික ශ්‍රම බලකායෙන් විශාල ප්‍රතිශතයක් අවිධිමත් අංශයේ නියැලී සිටී."),
      q(t, "ශ්‍රී ලංකාවේ 'බස්නාහිර පළාත් මහා නගර සැලසුම' (Western Region Megapolis) මගින් විසඳීමට අපේක්ෂා කළ ප්‍රධාන නාගරික ගැටලු මොනවාද?",
        "මාර්ග තදබදය, නාගරික ගංවතුර, ඝන අපද්‍රව්‍ය කළමනාකරණය, නිවාස හිඟය සහ සැලසුම්සහගත නවීන ව්‍යාපාර කලාප ඇති කිරීම", "වී වගාව නතර කිරීම", "සියලු වරාය වසා දැමීම", "උඩරට තේ ඉවත් කිරීම",
        "කොළඹ, ගම්පහ හා කළුතර දිස්ත්‍රික්ක ඒකාබද්ධ මහා නාගරික කලාපයක් ලෙස සැලසුම් කිරීම මීට අයත් වේ."),
      q(t, "ශ්‍රී ලංකාවේ වියළි කලාපයේ 1930 ගණන්වල සිට ක්‍රියාත්මක කළ 'ගොවි ජනපද ව්‍යාපාර' (Peasant Colonization Schemes - උදා: මින්නේරිය, ගල් ඔය, මහවැලි) ඇති කළ ප්‍රධාන ජනගහන බලපෑම කුමක්ද?",
        "අධික ජනගහනයක් සිටි තෙත් කලාපයේ ජනතාව වියළි කලාපයේ නව වාරි ගොවි ජනාවාසවල පදිංචි කර දිවයිනේ ජනගහන ව්‍යාප්තිය තුලනය කිරීම", "සියලු ගොවීන් විදේශගත කිරීම", "කොළඹට ජනතාව ගෙන ඒම", "වැව් විනාශ කිරීම",
        "ඩී.එස්. සේනානායක මහතාගේ මූලිකත්වයෙන් ඇරඹි ගොවි ජනපද ව්‍යාපාර වියළි කලාපයේ නව නගර හා කෘෂි ආර්ථිකයක් ගොඩනැගීය."),
      q(t, "'ජනගහන පිපිරුම' (Population Explosion) යන යෙදුම භාවිත කරනු ලබන්නේ 20 වන සියවසේ කුමන ගෝලීය සංසිද්ධිය විස්තර කිරීමටද?",
        "වෛද්‍ය විද්‍යාවේ හා ආහාර නිෂ්පාදනයේ දියුණුව නිසා ලෝක ජනගහනය බිලියන 2 සිට බිලියන 8 දක්වා ඉතා කෙටි කලකින් (වසර ~100 කින්) හතර ගුණයකින් පමණ වැඩි වීම", "ගිනිකඳු පිපිරීමක්", "නගර බෝම්බ දැමීමක්", "ග්‍රහක පතනයක්",
        "1927 දී බිලියන 2 ක් වූ ලෝක ජනගහනය 2022 නොවැම්බර් වන විට බිලියන 8 ඉක්මවීය."),
      q(t, "එක්සත් ජාතීන්ගේ ජනගහන ප්‍රක්ෂේපණ අනුව, ඉදිරි දශක කිහිපය තුළ ලෝකයේ වේගවත්ම ජනගහන වර්ධනයක් සිදු වීමට නියමිත මහාද්වීපය කුමක්ද?",
        "අප්‍රිකාව (විශේෂයෙන් උප-සහරා අප්‍රිකාව - නයිජීරියාව, කොංගෝ, ඉතියෝපියාව, ටැන්සානියාව)", "යුරෝපය", "උතුරු ඇමරිකාව", "ඔස්ට්‍රේලියාව",
        "යුරෝපයේ හා නැගෙනහිර ආසියාවේ ජනගහනය හැකිලෙන අතර අප්‍රිකාවේ තරුණ ජනගහනය වේගයෙන් ඉහළ යයි."),
      q(t, "'රූපාත්මක නාගරීකරණය' (Pseudo-urbanization / Over-urbanization) සංවර්ධනය වෙමින් පවතින රටවල දක්නට ලැබෙන්නේ කුමන ආකාරයෙන්ද?",
        "නගරයේ කාර්මික රැකියා හා යටිතල පහසුකම් නිර්මාණය වන වේගයට වඩා බෙහෙවින් වැඩි වේගයකින් ග්‍රාමීය දිළිඳු ජනතාව නගරවලට සංක්‍රමණය වී අවිධිමත් ජනාවාස වැඩිවීම", "නගර අලංකාර වීම", "සියලු දෙනාට සුඛෝපභෝගී නිවාස ලැබීම", "ග්‍රාමීය ජනගහනය වැඩිවීම",
        "මෙහිදී නගර විශාල වුවද සංවර්ධනය හා ජීවන තත්ත්වය ඊට සමානුපාතිකව ඉහළ නොයයි."),
      q(t, "'සැලසුම් කළ අගනුවරවල්' (Planned Capital Cities) ලෙස 20 වන සියවසේදී අලුතින් ඉදිකරන ලද නගර යුගලය කුමක්ද?",
        "බ්‍රසීලියා (බ්‍රසීලය) සහ ඉස්ලාමාබාද් (පකිස්ථානය) / කැන්බරා (ඔස්ට්‍රේලියාව)", "ලන්ඩන් සහ පැරිස්", "ටෝකියෝ සහ බීජිං", "රෝමය සහ ඇතැන්ස්",
        "වෙරළබඩ නගරවල තදබදය අඩු කිරීමට හා රට අභ්‍යන්තරය සංවර්ධනය කිරීමට රියෝ සිට බ්‍රසීලියා වෙත අගනුවර ගෙන යන ලදී."),
      q(t, "ශ්‍රී ලංකාවේ 'ශ්‍රී ජයවර්ධනපුර කෝට්ටේ' පරිපාලන අගනුවර ලෙස තෝරා ගැනීමෙන් අපේක්ෂා කළ භූගෝලීය අරමුණ කුමක්ද?",
        "කොළඹ වාණිජ නගරයේ තදබදය අඩු කර පරිපාලන හා පාර්ලිමේන්තු ආයතන තදාසන්න සැලසුම් කළ කලාපයකට විමධ්‍යගත කිරීම", "වරාය ගෙන යාම", "තේ වගාව ආරම්භ කිරීම", "ගුවන්තොටුපළ ඉදිකිරීම",
        "කොළඹ ශ්‍රී ලංකාවේ වාණිජ අගනුවර ලෙසත්, ශ්‍රී ජයවර්ධනපුර කෝට්ටේ නිල පරිපාලන අගනුවර ලෙසත් ක්‍රියා කරයි."),
      q(t, "ජනගහන ඝනත්වය දැක්වීම සඳහා තේමාත්මක සිතියම්කරණයේදී වඩාත් සුදුසු වන්නේ කුමන සිතියම් වර්ග දෙකද?",
        "තිත් සිතියම් (Dot Maps - නිරපේක්ෂ ව්‍යාප්තිය) සහ චෝරොප්ලෙත් සිතියම් (Choropleth Maps - ඝනත්වය)", "සමෝච්ච රේඛා සිතියම්", "මුහුදු ගැඹුරු සිතියම්", "තාරකා සිතියම්",
        "තිත් සිතියම් මගින් ගංගා නිම්න හා නගරවල ජනතාව රැස් වී සිටින ආකාරය ස්වාභාවිකව පෙන්වයි."),
      q(t, "'ජනගහන ලියාපදිංචි පද්ධති' (Civil Registration & Vital Statistics - CRVS) මගින් අඛණ්ඩව වාර්තා කරනු ලබන වැදගත් සිදුවීම් මොනවාද?",
        "සජීවී උපත්, මරණ, විවාහ සහ දික්කසාද", "වැසි හා සුළං", "භූමිකම්පා", "කෘෂි අස්වනු",
        "වසර 10 කට වරක් කෙරෙන සංගණනයට අමතරව වාර්ෂික උපත් හා මරණ අනුපාත ගණනය කිරීමට CRVS දත්ත භාවිත කෙරේ."),
      q(t, "ගෝලීය වශයෙන් 'උපත් අනුපාතයට වඩා මරණ අනුපාතය අඩු වීමත් සමඟ' මානව 'ආයු අපේක්ෂාව' (Life Expectancy at Birth) 1900 සිට අද දක්වා වෙනස් වූයේ කෙසේද?",
        "ලෝක සාමාන්‍ය ආයු අපේක්ෂාව වසර ~32 සිට වසර ~73 දක්වා දෙගුණයකටත් වඩා ඉහළ ගොස් ඇත", "වසර 30 දක්වා අඩු වී ඇත", "වෙනස් වී නැත", "වසර 150 දක්වා ගොස් ඇත",
        "ප්‍රතිජීවක ඖෂධ, එන්නත්, පිරිසිදු ජලය හා ළදරු සෞඛ්‍ය සේවා මෙම විප්ලවීය දියුණුවට හේතු විය."),
      q(t, "සංවර්ධනය වෙමින් පවතින රටවල අතීතයේ සිටම විශාල පවුල් (දරුවන් 5–8) අපේක්ෂා කිරීමට බලපෑ සමාජ-ආර්ථික හේතු මොනවාද?",
        "කෘෂිකාර්මික ශ්‍රමය සඳහා දරුවන්ගේ සහාය ලැබීම, ඉහළ ළදරු මරණ අනුපාතයට රක්ෂණයක් ලෙස හා මහලු වියේ රැකවරණය සඳහා", "විනෝද සංචාර යාමට", "විශාල මහල් නිවාස පිරවීමට", "රජයෙන් තහනම් කළ නිසා",
        "සමාජ ආරක්ෂණ ක්‍රම හා සෞඛ්‍ය පහසුකම් දියුණු වූ පසු දෙමාපියන් කුඩා පවුල් කෙරෙහි යොමු වේ."),
      q(t, "'නාගරික භූමි පරිභෝජන ගැටුම්' (Urban Land Use Conflicts) ඇතිවීමට ප්‍රධාන උදාහරණයක් වන්නේ කුමක්ද?",
        "නේවාසික ප්‍රදේශ අසල කර්මාන්තශාලා, ගුවන්තොටුපළ හෝ කසළ අංගණ පිහිටුවීමේදී ඇතිවන ශබ්ද, වායු දූෂණය හා පාරිසරික විරෝධතා (NIMBY)", "කුඹුරුවල වී වැපිරීම", "පාසල් අසල පුස්තකාල තැනීම", "උද්‍යානවල ගස් සිටුවීම",
        "NIMBY ('Not In My Backyard') යනු ප්‍රජාවට අවශ්‍ය වුවද තම නිවස අසල අප්‍රසන්න පහසුකම් ඉදිකිරීමට විරුද්ධ වීමයි."),
      q(t, "'ගම හා නගරය අතර අන්තර් රඳා පැවැත්ම' (Rural-Urban Interdependence) නිවැරදිව විස්තර කරන්නේ කුමන ප්‍රකාශයද?",
        "ග්‍රාමීය ප්‍රදේශ නගරයට ආහාර, අමුද්‍රව්‍ය, ජලය හා ශ්‍රමය සපයන අතර නගරය ගමට නිෂ්පාදිත භාණ්ඩ, බැංකු, උසස් සෞඛ්‍ය, අධ්‍යාපන හා වෙළඳපොළ පහසුකම් සපයයි", "ගම හා නගරය අතර කිසිදු සම්බන්ධයක් නැත", "නගරය ගමට වී සපයයි", "ගම නගරයට ගුවන් යානා සපයයි",
        "එබැවින් සමබර ප්‍රාදේශීය සංවර්ධනයක් සඳහා ග්‍රාමීය-නාගරික ප්‍රවාහන හා ආර්ථික සබඳතා ශක්තිමත් විය යුතුය."),
      q(t, "ජනාවාසයක් 'රේඩියල් / තාරකා හැඩැති' (Radial / Star-like Settlement) රටාවක් ගන්නේ කවර ස්ථානයකදීද?",
        "මාර්ග කිහිපයක් එක් මධ්‍යම හන්දියකට හමුවන (Crossroads / Nodal Point) ස්ථානයක සෑම මාර්ගයක් දිගේම නිවාස පිටතට විහිදෙන විට", "සෘජු වෙරළ තීරයකදී", "තනි ගංගා ඉවුරකදී", "කඳු මුදුනකදී",
        "බොහෝ වෙළඳ හා ප්‍රවාහන මංසන්ධි නගර මෙවැනි තාරකා හැඩැති ව්‍යාප්තියක් පෙන්නුම් කරයි."),
      q(t, "'මුහුදු බඩ නාගරීකරණය' (Coastal Urbanization) ලොව පුරා ඉතා ඉහළ මට්ටමක පවතින්නේ ඇයි?",
        "සාගර ප්‍රවාහනය හා වරාය වෙළඳාම, ධීවර කර්මාන්තය, සෞම්‍ය දේශගුණය සහ සංචාරක ආකර්ෂණය නිසා (ලෝක මෙගා නගර බොහොමයක් වෙරළාශ්‍රිතය)", "වෙරළේ හිම වැඩි නිසා", "කාන්තාර මැද නිසා", "ජලය ලවණ නිසා බීමට පහසු බැවින්",
        "නිව්යෝක්, ටෝකියෝ, ෂැංහයි, මුම්බායි, ලාගෝස් හා කොළඹ වැනි නගර මෙයට සාක්ෂි දරයි. කෙසේ වෙතත් මුහුදු මට්ටම ඉහළ යාමෙන් මෙම නගර දැඩි අවදානමක සිටී."),
      q(t, "ජනගහන විද්‍යාවේ 'මාතෘ මරණ අනුපාතය' (Maternal Mortality Ratio - MMR) රටක සංවර්ධන මට්ටම පෙන්වන දර්ශකයක් වන්නේ ඇයි?",
        "ගර්භණී හා ප්‍රසව සේවාවන්හි ගුණාත්මකභාවය, රෝහල් ප්‍රවේශ්‍යතාව සහ කාන්තා සෞඛ්‍ය හා පෝෂණ තත්ත්වය එමගින් පිළිබිඹු වන බැවින්", "කර්මාන්තශාලා ගණන මනින බැවින්", "වර්ෂාපතනය මනින බැවින්", "මාර්ග දිග මනින බැවින්",
        "ශ්‍රී ලංකාව දකුණු ආසියාවේ අඩුම මාතෘ හා ළදරු මරණ අනුපාතයක් වාර්තා කරන රටවලින් එකකි."),
      q(t, "'සාක්ෂරතා අනුපාතය' (Literacy Rate) ඉහළ මට්ටමක පැවතීම ජනගහනයේ ගුණාත්මකභාවය කෙරෙහි බලපාන්නේ කෙසේද?",
        "නිපුණ ශ්‍රම බලකායක් බිහිවීම, සෞඛ්‍ය පිළිබඳ දැනුවත්භාවය ඉහළ යාම, ඵලදායිතාව වැඩිවීම සහ දැනුවත් පවුල් සැලසුම් තීරණ ගැනීම", "කෘෂිකර්මය සම්පූර්ණයෙන් අවසන් වීම", "ජනගහනය රෝගී වීම", "කිසිදු වෙනසක් නැත",
        "ශ්‍රී ලංකාවේ සාක්ෂරතා අනුපාතය ~92%–93% ක ඉහළ අගයක පවතී."),
      q(t, "'මුඩුක්කු පුනරුත්ථාපනය' (Slum Upgrading) සඳහා වඩාත් සාර්ථක තිරසාර ප්‍රවේශය කුමක්ද?",
        "පදිංචිකරුවන් බලහත්කාරයෙන් ඉවත් නොකර, පිරිසිදු ජලය, වැසිකිළි, විදුලිය, ඉඩම් අයිතිය සහ අඩු පිරිවැය මහල් නිවාස/ආපදා ආරක්ෂිත පහසුකම් ලබා දීම", "බුල්ඩෝසර් යොදා කඩා දැමීම පමණි", "ඔවුන් කාන්තාරයට යැවීම", "පාරවල් වසා දැමීම",
        "ප්‍රජා සහභාගීත්වයෙන් යුත් නිවාස සංවර්ධන ව්‍යාපෘති නාගරික දිළිඳුකම අඩු කිරීමට උපකාරී වේ."),
      q(t, "ජනාවාසයක 'ප්‍රධාන කාර්යයන්' (Urban Functions) අනුව ඇනිවර්සිටි නගර (ඔක්ස්ෆර්ඩ්), ආගමික නගර (මහනුවර/මක්කම) සහ කාර්මික නගර (ඩෙට්‍රොයිට්/ෂෙන්ෂෙන්) ලෙස වර්ග කරන්නේ කුමන පදනම මතද?",
        "නගරයේ ආර්ථිකයට හා සමාජයට එම නගරය ඉටු කරන ප්‍රමුඛතම ක්‍රියාකාරී සේවාව අනුව", "නගරයේ නමේ අකුරු ගණන අනුව", "නගරයේ උසම ගස අනුව", "වැසි දින ගණන අනුව",
        "බොහෝ මහා නගර පරිපාලන, වාණිජ, සංස්කෘතික හා ප්‍රවාහන යන බහු කාර්යයන් (Multifunctional) ඉටු කරයි."),
      q(t, "'දේශගුණික සරණාගතයන්' (Climate Refugees / Environmental Migrants) යනු අනාගතයේදී වේගයෙන් වැඩි විය හැකි කුමන පිරිසක්ද?",
        "මුහුදු මට්ටම ඉහළ යාම (කුඩා දූපත් රාජ්‍ය), දීර්ඝ නියඟ, කාන්තාරකරණය හා දරුණු ගංවතුර නිසා තම නිජබිම් අතහැර යාමට සිදුවන ජනතාව", "ශීත ඍතු ක්‍රීඩා සඳහා යන සංචාරකයන්", "ගගනගාමීන්", "මුහුදු කොල්ලකරුවන්",
        "ටුවාලු, කිරිබාති, මාලදිවයින හා බංග්ලාදේශයේ පහත් බිම් වෙරළබඩ ජනතාව මෙම දැඩි අවදානමට මුහුණ දී සිටී."),
      q(t, "'ජාතික අනුපාතයට වඩා ශ්‍රී ලංකාවේ බස්නාහිර පළාතේ සමහර නගරවල දහවල් ජනගහනය (Daytime Population) රාත්‍රී ජනගහනයට වඩා බෙහෙවින් වැඩි වන්නේ' ඇයි?",
        "අවට දිස්ත්‍රික්කවලින් දිනපතා රැකියා, ව්‍යාපාර, පාසල් හා රෝහල් සේවා සඳහා ලක්ෂ සංඛ්‍යාත පිරිසක් කොළඹට පැමිණ සවස ආපසු යන බැවින්", "රාත්‍රියේදී මිනිසුන් සාගරයට යන නිසා", "කොළඹට පිටසක්වල ජීවීන් එන නිසා", "රාත්‍රියට නිවාස නැති නිසා",
        "දෛනික ගමනාගමනය (Commuting) නිසා කොළඹ නගරයේ දහවල් කාලයේ ජල, විදුලි, ප්‍රවාහන හා කසළ පීඩනය අතිශයින් ඉහළ යයි."),
      q(t, "ජනාවාස භූගෝල විද්‍යාවේ 'ග්‍රාමීය ප්‍රදේශවල ප්‍රතිවිකර්ෂණය / ජනගහන අඩුවීම' (Rural Depopulation) නිසා ගම්මානවලට ඇතිවන ඍණාත්මක බලපෑම කුමක්ද?",
        "තරුණ හා උගත් ශ්‍රම බලකාය නගරයට සංක්‍රමණය වීමෙන් ගමේ වැඩිහිටියන් පමණක් ඉතිරි වීම, පාසල්/තැපැල් හා බස් සේවා වැසී යාම සහ කෘෂි ඉඩම් පුරන් වීම", "ගමේ ගොවිපළවල් ඉබේම දියුණු වීම", "ගමේ ජන ඝනත්වය දස ගුණයකින් වැඩිවීම", "මාර්ග තදබදය වැඩි වීම",
        "ජපානයේ හා යුරෝපයේ දුරස්ථ ගම්මාන රැසක් මෙම ජනශූන්‍ය වීමේ අර්බුදයට මුහුණ දී සිටී."),
      q(t, "'නව නගර' (New Towns) හෝ 'චන්ද්‍රිකා නගර' (Satellite Towns) ඉදි කිරීමේ නාගරික සැලසුම් අරමුණ කුමක්ද?",
        "මව් මහා නගරයේ තදබදය හා නිවාස හිඟය සමනය කිරීම සඳහා නගරයෙන් පිටත, එහෙත් ප්‍රවාහන මාර්ගවලින් සම්බන්ධ වූ ස්වයංපෝෂිත නව නගර බිහි කිරීම", "මව් නගරය විනාශ කිරීම", "අභ්‍යවකාශයේ නගර තැනීම", "කෘෂිකර්මය තහනම් කිරීම",
        "ලන්ඩන් වටා මිල්ටන් කේන්ස් හෝ හොංකොං හි ෂා ටින් සහ ශ්‍රී ලංකාවේ හෝමාගම/කඩුවෙල වැනි සංවර්ධන කලාප මීට නිදසුන් වේ."),
      q(t, "'බහු-කාර්ය නාගරික ප්‍රවාහන පද්ධති' (Mass Rapid Transit - MRT / LRT / BRT) මහා නගර සඳහා අත්‍යවශ්‍ය වන්නේ ඇයි?",
        "පෞද්ගලික මෝටර් රථ භාවිතය අඩු කර අඩු ඉඩකින් වැඩි මගීන් පිරිසක් වේගයෙන් ප්‍රවාහනය කර තදබදය හා වායු දූෂණය අවම කිරීමට", "මාර්ග තදබදය වැඩි කිරීමට", "තෙල් පරිභෝජනය දෙගුණ කිරීමට", "පදිකයන් ඉවත් කිරීමට",
        "පොදු ප්‍රවාහනය කාර්යක්ෂම කිරීම තිරසාර නගරයක මූලික ලක්ෂණයකි."),
      q(t, "ජනගහන ඝනත්ව සංඛ්‍යාලේඛනවලදී 'මොනාකෝ' සහ 'සිංගප්පූරුව' ඉතා ඉහළ ජන ඝනත්වයක් පෙන්වීමට ප්‍රධාන හේතුව කුමක්ද?",
        "කුඩා භූමි ප්‍රමාණයක් සහිත සම්පූර්ණ නාගරික රාජ්‍යයන් (City-states) වීම", "විශාල කාන්තාර පැවතීම", "විශාල ගොවිපළවල් තිබීම", "ධ්‍රැව කලාපයේ පිහිටීම",
        "භූමි ප්‍රමාණය ඉතා කුඩා නගර රාජ්‍යයන්හි වර්ග කි.මී. ට ජන ඝනත්වය 8,000 සිට 25,000+ දක්වා ඉහළ අගයක් ගනී."),
      q(t, "'බංග්ලාදේශය' ලෝකයේ විශාල රටවල් අතර ඉහළම ජන ඝනත්වයක් (~වර්ග කි.මී. ට 1,200+) ඇති රටක් බවට පත්වීමට භූගෝලීය හේතුව කුමක්ද?",
        "රටේ භූමියෙන් බහුතරය ගංගා-බ්‍රහ්මපුත්‍ර-මේඝනා සාරවත් ඩෙල්ටා තැනිතලාව වීම නිසා ඉහළ කෘෂිකාර්මික ධාරිතාවක් හා කුඩා භූමියක විශාල ජනගහනයක් ජීවත් වීම", "රට සම්පූර්ණයෙන් කඳුකරයක් වීම", "විශාල කාන්තාරයක් වීම", "අයිස් තට්ටුවක් වීම",
        "මේ නිසා බංග්ලාදේශයේ ඩෙල්ටා ජනගහනය සුළි කුණාටු හා ගංවතුර ආපදාවලට දැඩි ලෙස නිරාවරණය වේ."),
      q(t, "'අන්තර්-වාර්ගික හා බහු-සංස්කෘතික නගර' (Cosmopolitan Cities - උදා: නිව්යෝක්, ලන්ඩන්, ටොරොන්ටෝ, සිංගප්පූරුව) බිහිවන්නේ කුමන ක්‍රියාවලිය නිසාද?",
        "විවිධ රටවලින් හා සංස්කෘතීන්ගෙන් පැමිණෙන ජාත්‍යන්තර සංක්‍රමණිකයන් නගරයේ ජීවත් වීම හා වැඩ කිරීම", "සියලු විදේශිකයන් තහනම් කිරීම", "ග්‍රාමීය හුදකලා බව", "වරායවල් වසා දැමීම",
        "විවිධත්වය නිසා මෙවැනි නගරවල ජනවාර්ගික අසල්වැසි ප්‍රදේශ (Chinatown, Little India) හා ගෝලීය වාණිජ ජාල බිහිවේ."),
      q(t, "ජනගහන අධ්‍යයනයේදී 'ස්වාභාවික වර්ධන අනුපාතය' ඍණ (-ve) අගයක් ගන්නේ කවර තත්ත්වයක් යටතේද?",
        "රටක වාර්ෂික මරණ සංඛ්‍යාව සජීවී උපත් සංඛ්‍යාව ඉක්මවා යන විට (උපත් < මරණ)", "උපත් මරණවලට වඩා වැඩි වන විට", "සංක්‍රමණිකයන් පැමිණෙන විට", "ආයු අපේක්ෂාව වැඩි වන විට",
        "බල්ගේරියාව, ලැට්වියාව, ඉතාලිය හා ජපානය සෘණ ස්වාභාවික වර්ධනයක් අත්විඳින රටවලට උදාහරණ වේ."),
      q(t, "'ශුන්‍ය ජනගහන වර්ධනය' (Zero Population Growth - ZPG) යනු කුමක්ද?",
        "උපත් + ආගමන සංඛ්‍යාව, මරණ + විගමන සංඛ්‍යාවට සමාන වී මුළු ජනගහනය ස්ථාවරව පවතින තත්ත්වය", "මුළු ජනගහනය බිංදුව වීම", "උපත් නොමැති වීම", "සංක්‍රමණය තහනම් වීම",
        "ස්ථාවර සම්පත් පරිභෝජනය හා තිරසාර සංවර්ධනය සඳහා ZPG තත්ත්වය වැදගත් සන්ධිස්ථානයක් ලෙස සැලකේ."),
      q(t, "ශ්‍රී ලංකාවේ 'මධ්‍යම කඳුකරයේ හා නිරිතදිග තෙත් කලාපයේ' ජන ඝනත්වය වියළි කලාපයට වඩා සාමාන්‍යයෙන් ඉහළ මට්ටමක පැවතීමට හේතුව කුමක්ද?",
        "වසර පුරා විශ්වාසදායක වර්ෂාපතනය, විවිධාංගීකරණය වූ කෘෂිකර්මය (තේ, රබර්, පොල්, කුළුබඩු) හා වාණිජ/කාර්මික පහසුකම් බහුල වීම", "වියළි කලාපයේ ජලය නොමැති වීම පමණි", "කඳුකරයේ හිම තිබීම", "තෙත් කලාපයේ කර්මාන්ත නොමැති වීම",
        "කොළඹ-ගම්පහ-කළුතර සහ මහනුවර-මාතලේ-කෑගල්ල දිස්ත්‍රික්ක ඉහළ ජනගහනයක් දරයි."),
      q(t, "ග්‍රාමීය හා අර්ධ-නාගරික ජනාවාසවල 'නිවාස ඉදිකිරීමේ සාම්ප්‍රදායික ද්‍රව්‍ය' (Vernacular Architecture) අතීතයේදී තීරණය වූයේ කුමන භූගෝලීය සාධකය මතද?",
        "ප්‍රදේශයේ දේශගුණය සහ අවට පරිසරයෙන් පහසුවෙන් ලබාගත හැකි දේශීය අමුද්‍රව්‍ය (මැටි, කබොක්, හුණුගල්, දැව, පොල් අතු, හිම/Igloo)", "විදේශීය වාස්තු විද්‍යාව", "අන්තර්ජාල සැලසුම්", "සඳේ ගුරුත්වය",
        "ශ්‍රී ලංකාවේ වියළි කලාපයේ වරිච්චි බිත්ති හා පිදුරු/ඉලුක් සෙවිලි කළ නිවාස අධික දහවල් රස්නය ඇතුළට ඒම වැළැක්වීය."),
      q(t, "'නාගරික අපද්‍රව්‍ය හා ඝන කසළ කළමනාකරණය' ලොව සෑම මහා නගරයකම දැවෙන ගැටලුවක් බවට පත්ව ඇත්තේ ඇයි?",
        "ඉහළ ජන ඝනත්වය හා පරිභෝජන රටා නිසා දිනපතා ටොන් දහස් ගණනක් කසළ ජනනය වීමත්, කසළ රඳවන භූමි (Landfills) හිඟ වීමත්", "මිනිසුන් කසළ ආහාරයට ගැනීම", "කසළ ඉබේ වාෂ්ප වීම", "නගරවල ඉඩම් වැඩිපුර තිබීම",
        "කසළ වෙන් කිරීම, ප්‍රතිචක්‍රීකරණය, කොම්පෝස්ට් නිෂ්පාදනය හා බලශක්ති ජනනය (Waste-to-Energy) මීට තිරසාර විසඳුම් වේ."),
      q(t, "'සාමූහික නිවාස' හෝ 'මහල් නිවාස සංකීර්ණ' (High-Rise Apartments) ඉදි කිරීම නාගරික සැලසුම්කරණයේදී වැදගත් වන්නේ කෙසේද?",
        "සිරස් වර්ධනය (Vertical Growth) මගින් කුඩා භූමි ප්‍රමාණයක් තුළ විශාල පවුල් සංඛ්‍යාවකට නිවාස ලබා දී හරිත අවකාශ හා කෘෂි ඉඩම් ඉතිරි කර ගැනීමට හැකිවීම", "වැඩි ඉඩම් ප්‍රමාණයක් නාස්ති කිරීමට", "මාර්ග දිගු කිරීමට", "සුළඟ නතර කිරීමට",
        "සිංගප්පූරුවේ HDB නිවාස පද්ධතිය සිරස් නාගරික නිවාසකරණයට ලෝක ප්‍රසිද්ධ ආදර්ශයකි."),
      q(t, "ජනගහන භූගෝල විද්‍යාවේ 'සහශ්‍ර පරම්පරා' හෝ 'තරුණ නෙරා යාම' (Youth Bulge) යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "මුළු ජනගහනයෙන් වයස අවුරුදු 15–29 අතර තරුණ ජනගහන ප්‍රතිශතය අතිශයින් ඉහළ මට්ටමක පැවතීම", "වයස 80 වැඩි පිරිස වැඩිවීම", "ළදරුවන් පමණක් සිටීම", "ජනගහනය සමාන වීම",
        "නිසි අධ්‍යාපන හා රැකියා අවස්ථා සැපයුවහොත් එය විශාල ආර්ථික ශක්තියක් වන අතර නොඑසේ නම් තරුණ විරැකියාව හා සමාජ අසහනය ඇතිවේ."),
      q(t, "'විස්ථාපනය වූ ජනාවාස' හෝ 'සංචාරක එඬේර ජනාවාස' (Nomadic Settlements) කුමන භූගෝලීය පරිසරවල තවමත් පවතීද?",
        "මධ්‍යම ආසියානු ස්ටෙප්ස් තණබිම් (මොංගෝලියාවේ Yurts/Gers), සහරා-අරාබි කාන්තාර (බෙදුවින්වරු) සහ ආක්ටික් ටුන්ඩ්‍රා කලාප", "කොළඹ නගර මධ්‍යයේ", "ටෝකියෝ උමං දුම්රියේ", "තෙත් වී කුඹුරුවල",
        "සතුන්ට තණකොළ හා ජලය සොයා ඍතු අනුව ගමන් කිරීමට පහසු වන ලෙස සැහැල්ලු හා ගැලවිය හැකි කූඩාරම් නිවාස භාවිත කෙරේ."),
      q(t, "ජනගහන පිරමීඩයක එක් එක් වයස් තීරුවක හදිසි 'හැකිලීමක් / කැපීමක්' (Indentation) දක්නට ලැබේ නම් ඉන් අදහස් වන්නේ කුමක්ද?",
        "එම වයස් කාණ්ඩය උපන් හෝ ජීවත් වූ කාලයේ සිදු වූ යුද්ධයක්, සාගතයක්, වසංගතයක් හෝ මහා විගමනයක් නිසා ජනගහනය අඩුවී ඇති බවයි", "සංගණන යන්ත්‍රය කැඩුණු බවයි", "සියලු දෙනා සතුටින් සිටින බවයි", "වර්ෂාව අඩු වූ බවයි",
        "උදාහරණයක් ලෙස දෙවන ලෝක යුද්ධය හෝ චීනයේ සාගත කාලපරිච්ඡේද ජනගහන පිරමීඩවල පැහැදිලිව සටහන් වී ඇත."),
      q(t, "'සැගවුණු ජනගහන වර්ධනය' හෙවත් 'ජනගහන ගම්‍යතාව' (Population Momentum) යනු කුමක්ද?",
        "සාඵල්‍යතා අනුපාතය ප්‍රතිස්ථාපන මට්ටමට (2.1) අඩු කළ පසුවත්, දැනටමත් ප්‍රජනක වයසේ පසුවන විශාල තරුණ කාන්තා පිරිස නිසා ජනගහනය තවත් දශක ගණනාවක් වැඩි වීම", "ජනගහනය එකවර නැවතීම", "මරණ වැඩි වීම", "විගමනය වැඩි වීම",
        "එබැවින් උපත් පාලන ප්‍රතිපත්තිවල සම්පූර්ණ බලපෑම පරම්පරා කිහිපයකට පසුව දක්නට ලැබේ."),
      q(t, "'ආයු අපේක්ෂාව' ස්ත්‍රී පුරුෂ භාවය අනුව සැලකීමේදී ගෝලීය සාමාන්‍යය අනුව වැඩි ආයු කාලයක් හිමි වන්නේ කාටද?",
        "කාන්තාවන්ට (පිරිමින්ට වඩා සාමාන්‍යයෙන් වසර 4–6 ක් පමණ වැඩියෙන්)", "පිරිමින්ට (වසර 20 ක් වැඩියෙන්)", "සමාන වේ (කිසිදා වෙනස් නොවේ)", "ළමුන්ට පමණි",
        "ජීව විද්‍යාත්මක සාධක මෙන්ම පිරිමින් අනතුරුදායක රැකියා හා සෞඛ්‍ය අවදානම්වලට වැඩියෙන් නිරාවරණය වීම මීට හේතු වේ."),
      q(t, "'අන්තර්-නාගරික ධුරාවලියේ' (Urban Hierarchy) පහළම සිට ඉහළම මට්ටම දක්වා නිවැරදි අනුපිළිවෙල කුමක්ද?",
        "හුදකලා නිවස → ගම්මානය → කුඩා නගරය → ප්‍රධාන නගරය (City) → මහා නගරය (Metropolis) → මෙගලෝපොලිස්", "මෙගලෝපොලිස් → ගම්මානය → නිවස", "නගරය → ගම → මහා නගරය", "ගම → මෙගලෝපොලිස් → කුඩා නගරය",
        "ධුරාවලියේ ඉහළට යත්ම ජනාවාස සංඛ්‍යාව අඩු වන නමුත් ඒවායේ ජනගහනය හා විශේෂිත සේවා පරාසය ඉහළ යයි."),
      q(t, "නගරයක 'රාත්‍රී-කාලීන ප්‍රවාහන හා නිදන නගර' (Dormitory Towns / Commuter Towns) යනුවෙන් හඳුන්වන්නේ කුමන ජනාවාසද?",
        "ප්‍රධාන මහා නගරයක රැකියා කරන ජනතාව රාත්‍රියේ නැවතී නිදා ගැනීම සඳහා පමණක් භාවිත කරන තදාසන්න නේවාසික නගර", "කර්මාන්තශාලා පමණක් ඇති නගර", "සංචාරක දූපත්", "වැව් ගම්මාන",
        "ශ්‍රී ලංකාවේ කොළඹ අවට මහරගම, කඩවත, පානදුර වැනි පෙදෙස්වලින් විශාල පිරිසක් දිනපතා කොළඹ රැකියා සඳහා පැමිණේ."),
      q(t, "'ආර්ථික සංක්‍රමණිකයන්' (Economic Migrants) සහ 'දේශපාලන සරණාගතයන්' අතර වෙනස කුමක්ද?",
        "ආර්ථික සංක්‍රමණිකයන් වඩා හොඳ රැකියා, වැටුප් හා ජීවන තත්ත්වයක් සොයා ස්වේච්ඡාවෙන් සංක්‍රමණය වන අතර සරණාගතයන් ජීවිතාරක්ෂාව පතා පලා යයි", "දෙගොල්ලන්ම යුද්ධය නිසා යයි", "ආර්ථික සංක්‍රමණිකයන්ට මුදල් අවශ්‍ය නැත", "කිසිදු වෙනසක් නැත",
        "ජාත්‍යන්තර නීතිය යටතේ සරණාගතයන්ට විශේෂ රැකවරණ හිමිකම් පවතී."),
      q(t, "'චක්‍රීය සංක්‍රමණය' (Circular Migration) යනු රටවල් අතර සිදුවන කුමන ශ්‍රම චලනයක්ද?",
        "සංක්‍රමණික ශ්‍රමිකයෙකු මව් රට හා විදේශීය රැකියා රට අතර කිහිප වරක්ම ගමන් කරමින් දැනුම හා ප්‍රාග්ධනය දෙපසටම හුවමාරු කිරීම ('Brain Circulation')", "එක් වරක් ගොස් කිසිදා නොඒම", "වෘත්තාකාර පාරක ඇවිදීම", "සතුන් සංක්‍රමණය වීම",
        "මෙම ක්‍රියාවලිය 'බුද්ධි ගලනය' (Brain Drain) 'බුද්ධි ප්‍රතිලාභයක්' (Brain Gain) බවට පත් කිරීමට උපකාරී වේ."),
      q(t, "සංවර්ධිත රටවල වයස්ගත වන ජනගහනය නිසා ඉහළම වර්ධනයක් පෙන්වන රැකියා හා සේවා අංශ මොනවාද?",
        "සෞඛ්‍ය සේවා, හෙද සේවා, වැඩිහිටි රැකවරණ මධ්‍යස්ථාන, ඖෂධ නිෂ්පාදනය සහ විශ්‍රාමික සංචාරක සේවා", "ළමා ඩයපර් හා සෙල්ලම් බඩු කර්මාන්ත", "ප්‍රාථමික පාසල් ඉදිකිරීම", "ළදරු ආහාර නිෂ්පාදනය",
        "ජනගහන වයස් ව්‍යුහය වෙනස් වීමත් සමඟ රටේ ආර්ථික හා වෙළඳපොළ ඉල්ලුමද ඊට අනුරූපව වෙනස් වේ."),
      q(t, "'ජනාවාසයක විහිදීම හා පිහිටීම' සිතියම්ගත කිරීමේදී ග්‍රාමීය පෙදෙස්වල 'කුඩා පොකුරු' (Hamlets) සහ 'ගම්මාන' (Villages) වෙන්කර හඳුනාගන්නේ කෙසේද?",
        "නිවාස සංඛ්‍යාව සහ එහි පවතින පාසල්, වෙළඳසැල්, ආගමික ස්ථාන හා තැපැල් කාර්යාල වැනි මූලික සේවා ප්‍රමාණය අනුව", "ගස් ගණන අනුව", "වැවේ වර්ණය අනුව", "දුරකථන කුළුණු ගණන අනුව",
        "Hamlet එකක නිවාස කිහිපයක් පමණක් ඇති අතර කිසිදු පොදු සේවාවක් නොතිබිය හැකිය."),
      q(t, "ශ්‍රී ලංකාවේ 'උතුරු හා නැගෙනහිර පළාත්වල' යුද ගැටුම් අවසන් වීමෙන් පසු ජනගහන භූගෝල විද්‍යාවේ දක්නට ලැබුණු ප්‍රධාන ක්‍රියාවලිය කුමක්ද?",
        "අවතැන් වූ ජනතාව නැවත පදිංචි වීම (Resettlement), ග්‍රාමීය යටිතල පහසුකම් ගොඩනැගීම සහ නාගරික වාණිජ කටයුතු ප්‍රකෘතිමත් වීම", "සියලු ජනතාව ඉවත් වීම", "කෘෂිකර්මය නතර වීම", "ධීවර කර්මාන්තය තහනම් වීම",
        "යාපනය, කිලිනොච්චි, මන්නාරම, මඩකලපුව හා ත්‍රිකුණාමලය නගර වේගයෙන් ප්‍රතිසංවර්ධනය වෙමින් පවතී."),
      q(t, "'ජනගහනය හා පරිසරයේ දරාගැනීමේ ධාරිතාව' (Carrying Capacity) යනු කුමක්ද?",
        "පාරිසරික පද්ධතියට ස්ථිර හානියක් නොවන පරිදි ජලය, ආහාර හා සම්පත් මගින් නිශ්චිත භූමි ප්‍රදේශයකට දිගු කාලීනව නඩත්තු කළ හැකි උපරිම ජනගහනය", "නගරයක ඇති බස් රථ ගණන", "පාලමක බර ඉසිලීමේ ශක්තිය", "වරායක නැව් ගණන",
        "තාක්ෂණික දියුණුව නිසා කෘෂි අස්වැන්න වැඩි වන විට මානව දරාගැනීමේ ධාරිතාවද ඉහළ ගොස් ඇත."),
      q(t, "'පාරිසරික පියසටහන' (Ecological Footprint) ඉහළ ජනගහනයක් සිටින රටකට වඩා ධනවත් කාර්මික රටක ඉතා ඉහළ අගයක් ගන්නේ ඇයි?",
        "සංවර්ධිත රටවල එක් පුද්ගලයෙකුගේ බලශක්ති, මාංශ, ඉලෙක්ට්‍රොනික හා භාණ්ඩ පරිභෝජනය සහ කාබන් විමෝචනය සංවර්ධනය වෙමින් පවතින රටක පුද්ගලයෙකුට වඩා බොහෝ ගුණයකින් වැඩි බැවින්", "ධනවත් රටවල ජනගහනය බිලියන 10 ක් නිසා", "ඔවුන් වැඩිපුර ඇවිදින නිසා", "ඔවුන් ගස් සිටුවන නිසා",
        "එබැවින් සම්පත් පරිභෝජන අර්බුදය ජනගහන සංඛ්‍යාව මත පමණක් නොව ඒක පුද්ගල පරිභෝජන රටාව මතද රඳා පවතී."),
      q(t, "'අවමංගල්‍ය හෝ මරණ අනුපාතයට' (Mortality) බලපාන සංවර්ධිත රටවල ප්‍රධාන රෝග රටාව කුමක්ද? (Epidemiological Transition)",
        "බෝවන රෝග වෙනුවට හෘද රෝග, පිළිකා, දියවැඩියාව වැනි බෝ නොවන නිදන්ගත රෝග (Degenerative Diseases) ප්‍රධාන වීම", "වසූරිය හා කොලරාව", "සර්ප දෂ්ටන", "කුසගින්න පමණි",
        "සෞඛ්‍ය හා සනීපාරක්ෂාව දියුණු වත්ම බෝවන රෝග පාලනය වී ජීවන රටා ආශ්‍රිත රෝග ප්‍රධාන වේ."),
      q(t, "ජනගහනය 'ලිංගික සමානුපාතයේ' (Sex Ratio) දකුණු ආසියාවේ හා නැගෙනහිර ආසියාවේ සමහර පෙදෙස්වල කාන්තාවන්ට වඩා පිරිමින් ප්‍රතිශතය වැඩි වීමට බලපෑ සමාජ හේතුව කුමක්ද?",
        "සමහර සමාජවල පුතුන් කෙරෙහි ඇති සංස්කෘතික කැමැත්ත (Son Preference) සහ ගැහැනු දරුවන්ට සෞඛ්‍ය හා පෝෂණ අවධානය අඩු වීම", "කාන්තාවන් විශ්වයට යාම", "ජලය ලවණ වීම", "ගැහැනු උපත් ස්වාභාවිකව අඩු වීම",
        "කාන්තා අධ්‍යාපනය හා නීතිමය රැකවරණය මගින් මෙම ස්ත්‍රී-පුරුෂ අසමතුලිතතාවය නිවැරදි කිරීමට පියවර ගෙන ඇත."),
      q(t, "ශ්‍රී ලංකාවේ 'නාගරික නිර්වචනය' (Official Urban Definition) ජාත්‍යන්තර සැසඳීම්වලදී අවතක්සේරු වීමට හේතුව කුමක්ද?",
        "මහ නගර සභා සහ නගර සභා සීමාවන් තුළ ජනතාව පමණක් 'නාගරික' ලෙස ගණන් ගන්නා අතර නාගරික ලක්ෂණ ඇති ප්‍රාදේශීය සභා තදාසන්න පෙදෙස් 'ග්‍රාමීය' ලෙස වර්ග කිරීම", "ශ්‍රී ලංකාවේ නගර නැති නිසා", "කොළඹ ගමක් ලෙස ගණන් ගන්නා නිසා", "ජනගහනය නොමැති නිසා",
        "නිල වශයෙන් නාගරික ප්‍රතිශතය ~18% වුවද, සැබෑ නාගරික හා අර්ධ-නාගරික ජීවන රටාවක් ඇති ජනතාව 35%–40% ඉක්මවයි."),
      q(t, "'නාගරික ගංවතුර' (Urban Flooding) ග්‍රාමීය ගංවතුරට වඩා වේගවත් හා දරුණු වීමට ප්‍රධාන හේතුව කුමක්ද?",
        "තාර, කොන්ක්‍රීට් හා වහලවල් වැනි අපාරගම්‍ය මතුපිටවල් (Impermeable Surfaces) වැඩි වීම නිසා වැසි ජලය පසට උරා නොගෙන ක්ෂණිකව මතුපිටින් ගලා යාම", "නගරයේ වර්ෂාව 10 ගුණයකින් වැඩි නිසා", "නගරයේ ගස් වැඩි නිසා", "මුහුද නගරය මැද ඇති නිසා",
        "තෙත් බිම් හා කුඹුරු ගොඩකිරීමත්, අවහිර වූ කාණු පද්ධතිත් කොළඹ වැනි නගරවල ක්ෂණික ගංවතුර උග්‍ර කරයි."),
      q(t, "ග්‍රාමීය ජනාවාසවලින් 'නාගරික ජනාවාස වෙත' තරුණ පිරිස ඇදී යාමට බලපාන ප්‍රධාන 'ඇදගැනීමේ සාධක' (Pull Factors) මොනවාද?",
        "විවිධාංගීකරණය වූ රැකියා අවස්ථා, උසස් අධ්‍යාපන ආයතන, නවීන සෞඛ්‍ය සේවා, විනෝදාස්වාදය සහ ඉහළ ජීවන පහසුකම්", "කෘෂිකාර්මික නියඟය", "ගමේ ගංවතුර", "රැකියා හිඟය",
        "තරුණ ජනතාව ගම හැර යාම නිසා ග්‍රාමීය සංවර්ධන ව්‍යාපෘති මගින් ගමේම ව්‍යවසායකත්ව අවස්ථා ඇති කිරීමට උත්සාහ කෙරේ."),
      q(t, "ජනගහන භූගෝල විද්‍යාවේ 'සේනාපති / ශ්‍රේණි-ප්‍රමාණ නීතිය' (Rank-Size Rule - George Zipf) අනුව රටක නගරවල ජනගහනය බෙදී යන්නේ කෙසේද?",
        "රටේ n වන විශාලතම නගරයේ ජනගහනය විශාලතම නගරයේ ජනගහනයෙන් 1/n ක් පමණ වේ (උදා: දෙවන නගරය ප්‍රධාන නගරයෙන් අඩකි)", "සියලු නගරවල ජනගහනය සමාන වේ", "දෙවන නගරය පළමු නගරය මෙන් දස ගුණයකි", "කුඩා නගර විශාල නගරවලට වඩා විශාලය",
        "ඇමරිකා එක්සත් ජනපදය මෙම නීතියට සමීපව අනුකූල වන අතර ප්‍රමුඛ නගර (Primate City) ඇති රටවල මෙයින් බැහැර වේ."),
      q(t, "විල්බර් සෙලින්ස්කිගේ 'සංචලතා සංක්‍රාන්ති ආකෘතිය' (Zelinsky's Mobility Transition Model) මගින් පෙන්වා දෙන්නේ කුමක්ද?",
        "රටක් ජන විකාශන සංක්‍රාන්තියේ (DTM) අදියර පසු කරන විට ජනතාවගේ සංක්‍රමණ රටාද (ග්‍රාමීය-නාගරික සිට නාගරික-තදාසන්න හා ජාත්‍යන්තර සංචලනය දක්වා) වෙනස් වන බව", "මිනිසුන් සංක්‍රමණය නොවන බව", "වාහන වේගය අඩුවන බව", "කඳු සංක්‍රමණය වන බව",
        "පූර්ව-නූතන සමාජවල සංක්‍රමණය අවම වන අතර දියුණු සමාජවල නගරාන්තර හා ජාත්‍යන්තර සංචලනය ඉහළ යයි."),
      q(t, "අර්නස්ට් රැවෙන්ස්ටයින්ගේ 'සංක්‍රමණ නීති' (Ravenstein's Laws of Migration) අනුව දුර බැහැර ජාත්‍යන්තර සංක්‍රමණිකයන් වැඩිපුරම ආකර්ෂණය වන්නේ කොතැනටද?",
        "ප්‍රධාන වාණිජ හා කාර්මික මහා නගර වෙත", "දුරස්ථ වනාන්තර වෙත", "කුඩා ගොවි ගම්මාන වෙත", "කාන්තාර මධ්‍යයට",
        "කෙටි දුර සංක්‍රමණ ගමේ සිට අසල නගරයට සිදුවන නමුත් දිගු දුර සංක්‍රමණිකයන් ප්‍රධාන ආර්ථික මධ්‍යස්ථාන තෝරා ගනී."),
      q(t, "රටක 'මධ්‍ය වයස' (Median Age) වසර 20 සිට වසර 42 දක්වා ඉහළ ගොස් තිබේ නම් ඉන් පෙන්නුම් කරන්නේ කුමක්ද?",
        "රටේ ජනගහනය සැලකිය යුතු ලෙස වයස්ගත වී ඇති අතර උපත් අනුපාතය අඩු වී ආයු අපේක්ෂාව ඉහළ ගොස් ඇති බවයි", "රටේ සියල්ලන්ම ළමුන් බවයි", "ළදරු මරණ 90% ක් බවයි", "උපත් අනුපාතය ඉතා ඉහළ බවයි",
        "නයිජර් වැනි රටවල මධ්‍ය වයස අවුරුදු 15 ක් පමණ වන අතර ජපානයේ හා ජර්මනියේ එය අවුරුදු 46–49 පමණ වේ."),
      q(t, "නාගරික භූගෝල විද්‍යාවේ 'ග්‍රාමීය-නාගරික සීමා තීරය' (Rural-Urban Fringe) යනුවෙන් හඳුන්වන්නේ කුමන ප්‍රදේශයද?",
        "නගරයේ ගොඩනැගුණු තදාසන්න පෙදෙස් හා අවට ග්‍රාමීය කෘෂිකාර්මික ඉඩම් එකිනෙක මිශ්‍ර වෙමින් පවතින සංක්‍රාන්ති කලාපය", "නගරයේ මධ්‍යම ව්‍යාපාරික දිස්ත්‍රික්කය", "සාගර පතුල", "ජාතික වනෝද්‍යානය මධ්‍යය",
        "නව නිවාස යෝජනා ක්‍රම, ගබඩා සංකීර්ණ, කර්මාන්ත උද්‍යාන සහ එළවළු/මල් වගා ගොවිපළවල් මෙම තීරයේ එකට පවතී."),
      q(t, "නගරවල 'පදික කලාප' (Pedestrian Zones) හා 'බයිසිකල් මංතීරු' (Cycling Lanes) පුළුල් කිරීමෙන් ලැබෙන නාගරික ප්‍රතිලාභ මොනවාද?",
        "වාහන දුම හා ශබ්ද දූෂණය අඩු වීම, මාර්ග අනතුරු අවම වීම, මහජන සෞඛ්‍යය දියුණු වීම සහ නගරයේ වෙළඳ ආකර්ෂණය ඉහළ යාම", "මාර්ග තදබදය වැඩි වීම", "ඉන්ධන පරිභෝජනය වැඩි වීම", "පදිකයන් අඩු වීම",
        "කෝපන්හේගන් සහ ඇම්ස්ටර්ඩෑම් නගර ලොව හොඳම බයිසිකල් හිතකාමී නාගරික ප්‍රවාහන ආදර්ශ සපයයි."),
      q(t, "ශ්‍රී ලංකාවේ 'මහනුවර' නගරය ආරම්භයේදී සාර්ථකව වර්ධනය වීමට බලපෑ ප්‍රධාන 'ස්ථානීය' (Site) සාධකය කුමක්ද?",
        "මහවැලි ගඟෙන් තුන් පැත්තක් ආවරණය වීම සහ හන්තාන-නකල්ස් කඳු වළල්ලෙන් වටවූ ස්වාභාවික ආරක්ෂිත නිම්නයක පිහිටීම", "සාගර වරායක් පැවතීම", "තෙල් නිධි පැවතීම", "විශාල කාන්තාරයක් වීම",
        "සතුරු ආක්‍රමණවලින් ආරක්ෂා වීමට මෙම භූගෝලීය පිහිටීම සෙන්කඩගල රාජධානියට ඉතා වාසිදායක විය."),
      q(t, "ශ්‍රී ලංකාවේ 'ගාල්ල' සහ 'ත්‍රිකුණාමලය' යන නගර බිහිවීමට හා වර්ධනය වීමට පදනම් වූ ප්‍රධාන භූගෝලීය සාධකය කුමක්ද?",
        "ස්වාභාවික බොකු ආශ්‍රිත වරායන් (Natural Harbours) හා සාගර වෙළඳ මාර්ගවල පිහිටීම", "උස කඳු මුදුන්", "මිරිදිය ඇලි", "හිම නිධි",
        "ගාල්ල ලන්දේසි කොටුව හා වරායද, ත්‍රිකුණාමලය කොඩ්ඩියාර් බොක්කද ඉන්දියන් සාගරයේ වැදගත් නාවික මධ්‍යස්ථාන විය."),
      q(t, "'ආභ්‍යන්තරික සංක්‍රමණ' (Internal Migration) අතර 'ගමෙන් ගමට සංක්‍රමණය' (Rural-to-Rural Migration) බහුලව සිදුවන්නේ කුමන අවස්ථාවලදීද?",
        "විවාහ වී වෙනත් ගමක පදිංචි වීම, නව වාරිමාර්ග/ගොවි ජනපද වෙත යාම හෝ වතු/කෘෂිකාර්මික කන්න රැකියා සඳහා ගමන් කිරීම", "විදේශ විශ්වවිද්‍යාලවලට යාම", "නිව්යෝක් නගරයට යාම", "අභ්‍යවකාශ ගමන්",
        "ශ්‍රී ලංකාවේ මහවැලි සංවර්ධන කලාප වෙත සිදුවූ ජන සංක්‍රමණය මීට ප්‍රධාන උදාහරණයකි."),
      q(t, "සංවර්ධනය වෙමින් පවතින රටවලට වඩා සංවර්ධිත රටවල (යුරෝපය, උතුරු ඇමරිකාව, ඔස්ට්‍රේලියාව) නාගරික ජනගහන ප්‍රතිශතය 80% ඉක්මවා ඇත්තේ ඇයි?",
        "කෘෂිකර්මය දැඩි ලෙස යාන්ත්‍රිකරණය වීම නිසා ගොවි බිම්වල අඩු ශ්‍රමිකයන් සංඛ්‍යාවක් අවශ්‍ය වීමත්, කාර්මික හා සේවා අංශ නගරවල ඒකරාශී වීමත්", "සංවර්ධිත රටවල ආහාර වගා නොකරන නිසා", "ගම්මාන නීතියෙන් තහනම් නිසා", "සියලු ගොවීන් මියගිය නිසා",
        "කෙසේ වෙතත් 21 වන සියවසේ වේගවත්ම නාගරික ජනගහන වර්ධනය සිදුවන්නේ ආසියාවේ හා අප්‍රිකාවේ නගරවලය."),
      q(t, "'සංක්‍රමණික සැපයුම් හා ජනගහන ජාල' (Ethnic Enclaves / Chain Migration) නගරවල නිර්මාණය වන්නේ කෙසේද?",
        "ප්‍රථමයෙන් විදේශ නගරයකට ගිය සංක්‍රමණිකයෙකුගේ මගපෙන්වීම හා ආධාර මත ඔහුගේ ඥාතීන් හා ගම්වැසියන්ද එම නගරයේ එකම අසල්වැසි පෙදෙසක පදිංචි වීම", "රජය විසින් බලෙන් එක තැනක තැබීම", "ගුවන් යානය අතරමග වැටීම", "අහඹු ලෙස විසිරී යාම",
        "Chain Migration නිසා නව සංක්‍රමණිකයන්ට නිවාස, රැකියා හා සංස්කෘතික සහයෝගය පහසුවෙන් හිමිවේ."),
      q(t, "ජනගහන දත්ත විශ්ලේෂණයේදී 'ශුද්ධ ප්‍රජනන අනුපාතය' (Net Reproduction Rate - NRR = 1.0) යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "වර්තමාන මරණ අනුපාත යටතේ එක් මවක් ඇය වෙනුවෙන් හරියටම එක් දුවක් ප්‍රජනන වයස දක්වා ජීවත් කරවීම", "සෑම මවකටම පුතුන් 10 ක් සිටීම", "කිසිදු දරුවෙකු නොලැබීම", "වැඩිහිටියන් 100% ක් වීම",
        "NRR < 1.0 නම් සංක්‍රමණ නොමැති විට දිගු කාලීනව ජනගහනය අඩුවීමේ ප්‍රවණතාවක් පෙන්නුම් කරයි."),
      q(t, "'නාගරික ක්ෂය වීම' (Urban Decay / Inner-City Decline) පැරණි කාර්මික නගරවල (උදා: ඩෙට්‍රොයිට්, ලිවර්පූල්) දක්නට ලැබුණේ ඇයි?",
        "සාම්ප්‍රදායික කර්මාන්ත වැසී යාම හෝ විදේශගත වීම, රැකියා නැතිවීම, මධ්‍යම පාන්තිකයන් තදාසන්න පෙදෙස්වලට යාම සහ නගර මධ්‍යයේ ගොඩනැගිලි නඩත්තු නොවීම", "කර්මාන්ත 10 ගුණයකින් වැඩිවීම", "ගුවන්තොටුපළ ඉදිකිරීම", "සංචාරකයන් වැඩිවීම",
        "මෙවැනි නගර යළි පණ ගැන්වීමට 'නාගරික පුනර්ජීවන' (Urban Regeneration) ව්‍යාපෘති ක්‍රියාත්මක කෙරේ."),
      q(t, "'මිශ්‍ර ඉඩම් පරිභෝජනය' (Mixed Land Use) නූතන තිරසාර නගර සැලසුම්කරණයේදී ප්‍රවර්ධනය කරන්නේ ඇයි?",
        "නිවාස, කාර්යාල, කඩසාප්පු, පාසල් හා උද්‍යාන එකිනෙකට පයින් යා හැකි දුරින් පිහිටුවා දිගු මෝටර් රථ ගමන් අවම කිරීමට ('15-Minute City' සංකල්පය)", "කර්මාන්තශාලා අසල රසායනික කසළ දැමීමට", "සියලු මාර්ග වැසීමට", "නගරය කාන්තාරයක් කිරීමට",
        "15-මිනිත්තු නගර සංකල්පය පදිකයන්ගේ ජීවන පහසුව හා කාබන් විමෝචනය අඩු කිරීම කෙරෙහි අවධානය යොමු කරයි."),
      q(t, "ජනාවාස භූගෝල විද්‍යාවේ 'සේවා රැසැයුම / අවම එළිපත්ත ජනගහනය' (Threshold Population) යනු කුමක්ද?",
        "යම් සේවාවක් හෝ වෙළඳසැලක් (උදා: විශේෂඥ රෝහලක් හෝ බේකරියක්) ආර්ථිකව පවත්වාගෙන යාමට අවශ්‍ය අවම ගනුදෙනුකරුවන් හෝ ජනගහන ප්‍රමාණය", "නගරයේ උසම ගොඩනැගිල්ල", "නිවසේ දොරකඩ උස", "ගමේ ඇති ගස් ගණන",
        "ප්‍රාථමික පාසලකට වඩා විශ්වවිද්‍යාලයකට ඉතා ඉහළ එළිපත්ත ජනගහනයක් (Threshold) හා පුළුල් සේවා පරාසයක් (Range) අවශ්‍ය වේ."),
      q(t, "ක්‍රිස්ටලර්ගේ න්‍යායේ 'භාණ්ඩයක හෝ සේවාවක පරාසය' (Range of a Good/Service) යනුවෙන් අදහස් කරන්නේ කුමක්ද?",
        "නිශ්චිත භාණ්ඩයක් හෝ සේවාවක් ලබා ගැනීම සඳහා පාරිභෝගිකයන් ගමන් කිරීමට සූදානම් වන උපරිම දුර ප්‍රමාණය", "භාණ්ඩයේ මිල ගණන", "ගොඩනැගිල්ලේ වර්ගඵලය", "වෙළඳසැලේ සේවක ගණන",
        "පාන් හා කිරි වැනි අඩු-පෙළ භාණ්ඩ සඳහා පරාසය කෙටි වන අතර, විශේෂිත ශල්‍යකර්ම හෝ මෝටර් රථ සඳහා පරාසය ඉතා දිගු වේ."),
      q(t, "'අවම ප්‍රවාහන පිරිවැය හා නැවත පදිංචි කිරීම' අවශ්‍ය වන 'සංවර්ධන නිසා ඇතිවන අවතැන් වීම' (Development-Induced Displacement) යනු කුමක්ද?",
        "මහා වේලි/ජලාශ (උදා: වික්ටෝරියා, කොත්මලේ, මොරගහකන්ද), අධිවේගී මාර්ග හා වරාය ඉදිකිරීමේදී ඉඩම් යටවීම නිසා පදිංචි ජනතාව නව ගම්මානවල පදිංචි කිරීම", "සුළි කුණාටු නිසා පලා යාම", "රැකියා සඳහා විදේශගත වීම", "විශ්වවිද්‍යාල සිසුන් සංක්‍රමණය",
        "කොත්මලේ ජලාශය ඉදිකිරීමේදී යටවූ කඩදොර වැනි ගම්මානවල ජනතාව කුණ්ඩසාලේ හා කොත්මලේ නව නගරයේ පදිංචි කරවන ලදී."),
      q(t, "ශ්‍රී ලංකාවේ වතු ආශ්‍රිත දිස්ත්‍රික්කයක් වන 'නුවරඑළියේ' ජනගහන හා ජනාවාස සැකැස්ම සෙසු දිස්ත්‍රික්කවලින් වෙනස් වන්නේ කෙසේද?",
        "මුළු ජනගහනයෙන් ~50% කට ආසන්න ඉහළ ප්‍රතිශතයක් වතු අංශයේ (Estate Sector) ජීවත් වීම සහ කඳු බෑවුම්වල විසිරුණු පේළි නිවාස සංකීර්ණ පැවතීම", "මුළු ජනගහනයම නාගරික වීම", "ධීවර ජනාවාස පමණක් පැවතීම", "සම්පූර්ණයෙන් කාන්තාර ජනාවාස වීම",
        "ශ්‍රී ලංකාවේ වැඩිම වතු ජනගහනයක් ජීවත් වන දිස්ත්‍රික්කය නුවරඑළිය වේ."),
      q(t, "ජනගහන භූගෝල විද්‍යාවේ 'අධි ජනගහනය' (Overpopulation) යනු කුමක්ද?",
        "යම් ප්‍රදේශයක පවතින සම්පත්, ආහාර, ජලය හා රැකියා අවස්ථා ප්‍රමාණයට වඩා ජනගහනය වැඩි වී ජීවන තත්ත්වය පහත වැටීම", "වර්ග කිලෝමීටරයට 100 ක් සිටීම පමණි", "රටේ ප්‍රමාණය විශාල වීම", "නගර තිබීම",
        "සිංගප්පූරුවේ ජන ඝනත්වය ඉතා ඉහළ වුවද සම්පත් හා ආර්ථික ධාරිතාව ඉහළ නිසා එය අධි ජනගහන රටක් ලෙස නොසැලකේ."),
      q(t, "'ඌන ජනගහනය' (Underpopulation) ඇති රටකට (උදා: කැනඩාව, ඔස්ට්‍රේලියාව, මොංගෝලියාව) සංවර්ධන කටයුතුවලදී මුහුණ දීමට සිදුවන ප්‍රධාන ගැටලුව කුමක්ද?",
        "රටේ පවතින විශාල ස්වාභාවික සම්පත් හා ඉඩම් සම්පූර්ණයෙන් ප්‍රයෝජනයට ගැනීමට ප්‍රමාණවත් ශ්‍රම බලකායක් හා දේශීය වෙළඳපොළක් නොමැති වීම", "ආහාර මදිවීම", "ඉඩම් හිඟය", "අධික මාර්ග තදබදය",
        "එබැවින් මෙම රටවල් පුහුණු විදේශීය සංක්‍රමණිකයන්ට ස්ථිර පදිංචිය ලබා දීමට විශේෂ වැඩසටහන් ක්‍රියාත්මක කරයි."),
      q(t, "නාගරික භූගෝල විද්‍යාවේ 'සමාජීය බෙදී යාම / නේවාසික වෙන්වීම' (Residential Segregation) ඇති වන්නේ කුමන සාධක පදනම් කරගෙනද?",
        "ආදායම් මට්ටම, සමාජ පන්තිය, ජනවාර්ගිකත්වය, භාෂාව හෝ ආගම මත එකම කණ්ඩායම් නගරයේ නිශ්චිත කොටස්වල ඒකරාශී වීම", "වාහන වර්ණය මත", "උස අඩු වැඩි බව මත", "වර්ෂාපතනය මත",
        "ධනවතුන්ගේ ආරක්ෂිත නිවාස සංකීර්ණ (Gated Communities) හා අඩු ආදායම් මුඩුක්කු පෙදෙස් අතර විශාල සමාජ පරතරයක් ඇතිවිය හැකිය."),
      q(t, "ජනගහන අනුපාත ගණනය කිරීමේදී 'ළමා යැපුම් අනුපාතය' (Youth Dependency Ratio) අඩු වන විට රජයකට ලැබෙන ආර්ථික වාසිය කුමක්ද?",
        "ප්‍රාථමික පාසල් හා ළමා සුබසාධන වියදම්වල පීඩනය අඩු වී යටිතල පහසුකම්, උසස් අධ්‍යාපනය හා කර්මාන්ත සංවර්ධනයට වැඩිපුර ආයෝජනය කළ හැකි වීම", "විශ්‍රාම වැටුප් වියදම ශුන්‍ය වීම", "ගුරුවරුන් අවශ්‍ය නොවීම", "බදු ආදායම නැති වීම",
        "මෙය ආර්ථික සංවර්ධනය සඳහා ජන විකාශන කවුළුව (Demographic Window of Opportunity) විවෘත කරයි."),
      q(t, "'වැඩිහිටි යැපුම් අනුපාතය' (Old-Age Dependency Ratio) වේගයෙන් ඉහළ යන විට රාජ්‍ය මූල්‍ය පද්ධතියට ඇති වන ප්‍රධාන පීඩනය කුමක්ද?",
        "වැඩ කරන තරුණ බදු ගෙවන්නන් සංඛ්‍යාව සාපේක්ෂව අඩු වන විට විශ්‍රාම වැටුප්, නිදන්ගත රෝග ප්‍රතිකාර හා වැඩිහිටි රැකවරණ වියදම් විශාල ලෙස ඉහළ යාම", "පෙර පාසල් හිඟවීම", "ළමා සෙල්ලම් බඩු මිල ඉහළ යාම", "රැකියා කරන වයස 10 දක්වා අඩු වීම",
        "ශ්‍රී ලංකාවද 2040 වන විට ජනගහනයෙන් ~25% ක් වයස 60 ට වැඩි වන බැවින් දායක විශ්‍රාම ක්‍රම හා වැඩිහිටි සෞඛ්‍ය සේවා ශක්තිමත් කළ යුතුය."),
      q(t, "ග්‍රාමීය ජනාවාසවල 'නියඟය හා වාරි පද්ධති බිඳවැටීම' ජනගහන සංක්‍රමණය කෙරෙහි බලපාන්නේ කෙසේද?",
        "කෘෂි අස්වනු පාඩු වීම හා ණය බර වැඩිවීම නිසා ගොවි පවුල්වල සාමාජිකයන් ඇඟලුම්, ඉදිකිරීම් හා සේවා රැකියා සොයා නාගරික කලාපවලට හෝ විදේශ රටවලට සංක්‍රමණය වීම", "නාගරිකයන් ගමට ඒම", "වී වගාව දෙගුණ වීම", "ජනගහනය නොවෙනස්ව පැවතීම",
        "දේශගුණික අස්ථාවරත්වය ග්‍රාමීය-නාගරික සංක්‍රමණයේ ප්‍රධාන තල්ලු සාධකයකි."),
      q(t, "මහා නගරවල 'පොදු අවකාශයන්' (Public Spaces - උද්‍යාන, පදික චතුරශ්‍ර, වෙරළ තීර, පුස්තකාල) සංරක්ෂණය කිරීම වැදගත් වන්නේ ඇයි?",
        "මානසික හා ශාරීරික සෞඛ්‍යය ප්‍රවර්ධනය කිරීම, සමාජ එකමුතුව වැඩි දියුණු කිරීම, නාගරික උෂ්ණත්වය අඩු කිරීම සහ වැසි ජලය පොළොවට උරා ගැනීම", "වාහන නැවැත්වීමේ ගාස්තු අඩු කිරීමට පමණි", "ඉඩම් මිල බිංදුවට දැමීමට", "වන සතුන් ඇති කිරීමට පමණි",
        "කොළඹ විහාරමහාදේවී උද්‍යානය, ගාලු මුවදොර පිටිය හා දියත උයන නාගරික ප්‍රජාවට ඉතා වැදගත් හරිත හා විවෘත අවකාශයන් වේ."),
      q(t, "'ජාත්‍යන්තර සංක්‍රමණ සංවිධානය' (IOM) සහ 'UNHCR' අතර කාර්යභාරයේ ප්‍රධාන වෙනස කුමක්ද?",
        "IOM ආයතනය සංවර්ධන හා සේවා නියුක්ති සංක්‍රමණ ඇතුළු සියලු සංක්‍රමණ කළමනාකරණයට සහාය වන අතර UNHCR ආයතනය විශේෂයෙන් යුද හා පීඩන හේතුවෙන් අවතැන් වූ සරණාගතයන් ආරක්ෂා කරයි", "දෙකම ක්‍රිකට් සංවිධාන වේ", "IOM ගුවන් යානා නිපදවයි", "UNHCR හෝටල් පවත්වාගෙන යයි",
        "ආරක්ෂිත, ක්‍රමවත් හා නිත්‍යානුකූල සංක්‍රමණය තිරසාර සංවර්ධන ඉලක්කවල (SDG 10.7) කොටසකි."),
      q(t, "'විවෘත දේශසීමා / කලාපීය ශ්‍රම සංචලනය' (Regional Labour Mobility - උදා: යුරෝපා සංගමයේ ෂෙන්ගන් කලාපය) ජනගහන ව්‍යාප්තියට බලපාන්නේ කෙසේද?",
        "වීසා බාධකවලින් තොරව සාමාජික රටවල් අතර රැකියා, අධ්‍යාපනය හා පදිංචිය සඳහා ජනතාවට පහසුවෙන් ගමන් කිරීමට හැකිවීම", "රටවල් අතර තාප්ප බැඳීම", "වෙළඳාම නතර වීම", "සංක්‍රමණය ශුන්‍ය වීම",
        "නැගෙනහිර යුරෝපයේ රටවලින් බටහිර යුරෝපයේ ආර්ථික මධ්‍යස්ථාන වෙත විශාල තරුණ ශ්‍රම සංචලනයක් මේ හරහා සිදු වී ඇත."),
      q(t, "ජනාවාස භූගෝල විද්‍යාවේ 'ආර්ථික සංවර්ධනයත් සමඟ ග්‍රාමීය ජනාවාස ව්‍යුහයේ සිදුවන පරිවර්තනය' කුමක්ද?",
        "කෘෂි රැකියා අඩු වී කෘෂි-සැකසුම්, සංචාරක, ප්‍රවාහන හා තාක්ෂණ සේවා ගමට පැමිණීමත් සමඟ ගම්මාන කුඩා නාගරික මධ්‍යස්ථාන බවට පරිණාමය වීම", "සියලු පාරවල් ගලවා ඉවත් කිරීම", "විදුලිය විසන්ධි කිරීම", "මිනිසුන් ගල් ගුහාවලට යාම",
        "මෙය 'ග්‍රාමීය පරිවර්තනය' (Rural Transformation) ලෙස හැඳින්වේ."),
      q(t, "'කාර්මික නගරයක සිට පශ්චාත්-කාර්මික දැනුම හා සේවා නගරයක්' (Post-Industrial Knowledge City) බවට පරිවර්තනය වූ නගරවලට උදාහරණ මොනවාද?",
        "ලන්ඩන්, පිට්ස්බර්ග්, සෝල් සහ ටෝකියෝ (බර කර්මාන්ත වෙනුවට මූල්‍ය, මෘදුකාංග, පර්යේෂණ හා සංස්කෘතික කර්මාන්ත ප්‍රමුඛ වීම)", "ඇමසන් වැසි වනාන්තරය", "සහරා ක්ෂේම භූමි", "අයිස්ලන්ත ග්ලැසියර",
        "නගරයේ පැරණි කර්මාන්තශාලා ගබඩා නවීන තාක්ෂණ උද්‍යාන හා විශ්වවිද්‍යාල කලාප බවට පත් කෙරේ."),
      q(t, "'ග්‍රාමීය අවශ්‍යතා සඳහා කලාපීය සේවා මධ්‍යස්ථාන' (Regional Growth Centres) කුඩා නගර ලෙස සංවර්ධනය කිරීම වැදගත් වන්නේ ඇයි?",
        "අධ්‍යාපන, සෞඛ්‍ය, බැංකු හා වෙළඳ පහසුකම් ගම අසලින්ම ලබා දී රටේ ප්‍රධාන අගනුවර වෙත එල්ල වන අධික සංක්‍රමණ පීඩනය අඩු කිරීමට", "අගනුවර ජනශූන්‍ය කිරීමට", "ගමේ පාසල් වැසීමට", "පොදු ප්‍රවාහනය නතර කිරීමට",
        "ශ්‍රී ලංකාවේ කුරුණෑගල, අනුරාධපුර, රත්නපුර, බදුල්ල හා මාතර වැනි ප්‍රාදේශීය නගර දියුණු කිරීම මීට මනා නිදසුනකි."),
      q(t, "ජනගහනය 'වෘත්තීය ව්‍යුහය' (Occupational Structure) අනුව රටක් සංවර්ධිත මට්ටමක පවතින බව හඳුනා ගන්නේ කෙසේද?",
        "ශ්‍රම බලකායෙන් ඉතා සුළු ප්‍රතිශතයක් (2%–5%) ප්‍රාථමික අංශයේද, සැලකිය යුතු කොටසක් ද්විතීයික අංශයේද, බහුතරයක් (70%+) තෘතීයික හා චතුර්ථක සේවා අංශවලද නියැලී සිටින විට", "90% ක් ගොවිතැනේ නියැලී සිටින විට", "කිසිවෙකු සේවා අංශයේ නැති විට", "සියල්ලන්ම රැකියා විරහිත විට",
        "ආර්ථික සංවර්ධනය සමඟ ශ්‍රම බලකාය කෘෂිකර්මයේ සිට කර්මාන්ත හා සේවා අංශ වෙත මාරු වේ (Clark-Fisher Model)."),
      q(t, "'සංක්‍රමණිකයන්ගේ තත්ත්වය හා අයිතිවාසිකම්' සුරැකීම ජනගහන භූගෝල විද්‍යාවේ වැදගත් මාතෘකාවක් වන්නේ ඇයි?",
        "අවිධිමත් හා නීතිවිරෝධී මිනිස් ජාවාරම් වැළැක්වීම, සාධාරණ වැටුප්, සෞඛ්‍ය ආරක්ෂණය සහ පවුල් සුබසාධනය තහවුරු කිරීම සඳහා", "වීසා ගාස්තු වැඩි කිරීමට පමණි", "ගුවන් තොටුපළ වැසීමට", "සංක්‍රමණ සම්පූර්ණයෙන් තහනම් කිරීමට",
        "විශේෂයෙන් ගෘහ සේවිකාවන් හා ඉදිකිරීම් ශ්‍රමිකයන් ආරක්ෂා කිරීම සඳහා ද්විපාර්ශ්වික රාජ්‍ය ගිවිසුම් වැදගත් වේ."),
      q(t, "ජනගහනය 'සෞඛ්‍ය සම්පන්නව වයස්ගත වීම' (Healthy Ageing) සඳහා නාගරික හා ග්‍රාමීය ජනාවාස සැලසුම් කළ යුත්තේ කෙසේද?",
        "ප්‍රවේශ වීමට පහසු පදික වේදිකා, බැස යාමට පහසු බස් රථ, ප්‍රජා සෞඛ්‍ය මධ්‍යස්ථාන, ව්‍යායාම උද්‍යාන හා අන්තර්-පරම්පරා ප්‍රජා මධ්‍යස්ථාන ඉදිකිරීමෙන්", "පඩිපෙළවල් ඉතා උස් කිරීමෙන්", "උද්‍යාන ඉවත් කිරීමෙන්", "වෛද්‍යවරුන් අඩු කිරීමෙන්",
        "ලෝක සෞඛ්‍ය සංවිධානය (WHO) 'වැඩිහිටි-හිතකාමී නගර' (Age-friendly Cities) සංකල්පය මේ සඳහා හඳුන්වා දී ඇත."),
      q(t, "'ජන සංඛ්‍යා ලේඛන විද්‍යාවේ' (Demography) පළමු නූතන විද්‍යාත්මක විශ්ලේෂණ ක්‍රම අතර 'ජීවිත වගුව' (Life Table) භාවිත කරන්නේ කුමක් සඳහාද?",
        "එක් එක් වයස් කාණ්ඩයේ පුද්ගලයෙකු මියයාමේ හෝ ජීවත් වීමේ සම්භාවිතාව සහ ඉතිරි ආයු අපේක්ෂාව ගණනය කිරීමට", "රටේ භූමි ප්‍රමාණය මැනීමට", "වැසි වගු සෑදීමට", "මැතිවරණ ඡන්ද ගණන් කිරීමට",
        "රක්ෂණ සමාගම්, විශ්‍රාම අරමුදල් හා ජාතික සෞඛ්‍ය සැලසුම්කරණයේදී ජීවිත වගු අත්‍යවශ්‍ය මෙවලමකි."),
      q(t, "සංවර්ධනය වෙමින් පවතින රටවල 'නාගරික ප්‍රදේශවල විරැකියාවට වඩා ඌන සේවා නියුක්තිය' (Underemployment) බහුල වන්නේ ඇයි?",
        "බොහෝ දෙනා සම්පූර්ණයෙන් රැකියා විරහිතව නොසිටියත් ඔවුන්ගේ අධ්‍යාපන සුදුසුකම්වලට හෝ කාලයට නොගැළපෙන අඩු වැටුප් අර්ධ-කාලීන රැකියාවල නිරත වීමට සිදුවීම නිසා", "කිසිවෙකු වැඩ කිරීමට අකමැති නිසා", "වැටුප් ඉතා ඉහළ නිසා", "රැකියා පමණට වඩා ඇති නිසා",
        "තරුණ උපාධිධාරීන්ගේ නිපුණතා ආර්ථිකයේ ඉල්ලුමට නොගැළපීම (Skills Mismatch) මෙම ගැටලුව තීව්‍ර කරයි."),
      q(t, "ජනාවාස භූගෝල විද්‍යාවේ 'සේවා නගර හා ප්‍රවාහන මධ්‍යස්ථාන' (Transport Hubs / Break-of-Bulk Points) විශාල නගර බවට පත්වීමට හේතුව කුමක්ද?",
        "භාණ්ඩ එක් ප්‍රවාහන මාධ්‍යයකින් තවත් මාධ්‍යයකට (උදා: නැවෙන් දුම්රියට හෝ ට්‍රක් රථයට) මාරු කරන ස්ථානවල ගබඩා, ඇසුරුම්, බැංකු හා සැකසුම් කර්මාන්ත ගොඩනැගීම", "ගමන් කිරීම තහනම් කිරීම", "මාර්ග අවසන් වීම", "කඳු හරස් කිරීමට නොහැකි වීම",
        "රොටර්ඩෑම්, සිංගප්පූරුව, චිකාගෝ හා කොළඹ ලොව ප්‍රධාන Break-of-Bulk ප්‍රවාහන නගර වේ."),
      q(t, "'දේශීය හා ගෝලීය නාගරික ජාල' (Global Cities / World Cities - උදා: නිව්යෝක්, ලන්ඩන්, ටෝකියෝ) අනෙකුත් මෙගා නගරවලින් වෙනස් වන්නේ කෙසේද?",
        "ඒවායේ ජනගහනය පමණක් නොව, ලෝක ආර්ථිකය, ජාත්‍යන්තර බැංකු, කොටස් වෙළඳපොළ, බහුජාතික සමාගම් මූලස්ථාන හා සන්නිවේදන ජාල පාලනය කිරීමේ බලය පැවතීම", "ඒවා කුඩා ගම්මාන වීම", "ඒවායේ බැංකු නොමැති වීම", "ඒවා කෘෂිකාර්මික වීම",
        "සස්කියා සැසන් (Saskia Sassen) විසින් හඳුන්වා දුන් 'Global Cities' සංකල්පය ගෝලීයකරණයේ කේන්ද්‍රස්ථාන හඳුනා ගනී."),
      q(t, "'නාගරික තාප ආතතිය' (Urban Heat Stress) වැඩි වශයෙන්ම බලපාන සමාජ කණ්ඩායම් කවුරුන්ද?",
        "වැඩිහිටියන්, කුඩා දරුවන්, එළිමහන් කම්කරුවන් හා වායු සමීකරණ රහිත අඩු ආදායම් නිවාසවල ජීවත් වන්නන්", "වායු සමීකරණ කාර්යාල සේවකයන් පමණි", "ධ්‍රැව කලාපීය වැසියන්", "සාගර නාවිකයන්",
        "නගරවල සෙවණ දෙන ගස් සිටුවීම හා සිසිල් නවාතැන් (Cooling Centers) පිහිටුවීම දේශගුණික අනුවර්තනයට වැදගත් වේ."),
      q(t, "ජනගහන අධ්‍යයනයේදී 'නිත්‍ය පදිංචිකරුවන්' (Residents) සහ 'සෘතුමය සංචාරකයන්' (Seasonal Tourists) අතර වෙනස හඳුනා ගැනීම වෙරළ නගරවලට වැදගත් වන්නේ ඇයි?",
        "සංචාරක සමයේදී ජලය, විදුලිය, කසළ හා ප්‍රවාහන ඉල්ලුම ස්ථිර ජනගහනයට වඩා කිහිප ගුණයකින් ඉහළ යන බැවින්", "සංචාරකයන් ජලය භාවිත නොකරන බැවින්", "සංචාරකයන් ගෙවල් ඉදි කරන බැවින්", "කිසිදු බලපෑමක් නැති බැවින්",
        "හික්කඩුව, ඇල්ල, නුවරඑළිය හා ආරුගම් බේ වැනි නගරවල යටිතල පහසුකම් උච්ච සමය අනුව සැලසුම් කළ යුතුය."),
      q(t, "'මුහුදු මට්ටම ඉහළ යාම හේතුවෙන් අගනුවර රට අභ්‍යන්තරයට මාරු කිරීමට' තීරණය කළ ආසියානු රට කුමක්ද?",
        "ඉන්දුනීසියාව (ගිලෙමින් පවතින ජකර්තා නගරයේ සිට බෝර්නියෝ දූපතේ 'නුසන්තාරා' වෙත අගනුවර ගෙන යාම)", "නේපාලය", "භූතානය", "ලාවෝසය",
        "භූගත ජලය අධික ලෙස පොම්ප කිරීම නිසා ගිලා බැසීම (Land Subsidence) හා ජනගහන තදබදය ජකර්තා නගරයට දැඩි තර්ජනයක් විය."),
      q(t, "'අවම ප්‍රවාහන ජාල හා සේවා පහසුකම්' ඇති 'දුරස්ථ ග්‍රාමීය ජනාවාස' (Remote Rural Settlements) වල ජීවන තත්ත්වය නැංවීමට වර්තමානයේ යොදා ගන්නා ප්‍රබල මෙවලම කුමක්ද?",
        "අධිවේගී අන්තර්ජාලය, ටෙලි-වෛද්‍ය සේවා (Telemedicine), දුරස්ථ අධ්‍යාපනය (e-Learning) සහ ජංගම බැංකු සේවා", "සියලු පාසල් වැසීම", "දුරකථන කුළුණු ඉවත් කිරීම", "බස් රථ නතර කිරීම",
        "ඩිජිටල් සම්බන්ධතාවය (Digital Connectivity) ග්‍රාමීය හුදකලා බව අඩු කර ගොවීන්ට සෘජු වෙළඳපොළ තොරතුරු ලබා දෙයි."),
      q(t, "ජනාවාසයක 'ප්‍රවේශ්‍යතාව' (Accessibility) ඉහළ යාමෙන් නගරයේ ඉඩම් පරිභෝජනයට සිදුවන බලපෑම කුමක්ද?",
        "නව අධිවේගී මාර්ගයක් හෝ දුම්රිය නැවතුම්පොළක් අවට ඉඩම් මිල ඉහළ ගොස් වාණිජ, කාර්යාල හා මහල් නිවාස සංවර්ධනය වේගවත් වේ", "සියලු දෙනා එතැනින් ඉවත් වේ", "ඉඩම් මිල බිංදුව වේ", "එහි වනාන්තරයක් ඉබේම හැදේ",
        "ශ්‍රී ලංකාවේ දක්ෂිණ අධිවේගී මාර්ගයේ පිවිසුම් (කඩවත, කොට්ටාව, දොඩංගොඩ, කුරුඳුගහහැතැප්ම) අවට නාගරීකරණය මීට නිදසුනකි."),
      q(t, "'නාගරික අපරාධ හා සමාජ අසහනය' අවම කිරීමට ජනාවාස සැලසුම්කරුවන් යෝජනා කරන 'පාරිසරික සැලසුම් මගින් අපරාධ වැළැක්වීම' (CPTED) යනු කුමක්ද?",
        "හොඳ වීදි ආලෝකකරණය, විවෘත හා දර්ශනය වන පොදු උද්‍යාන, සක්‍රීය වීදි මුහුණත් සහ ප්‍රජා හිමිකාරිත්වය ඇති කිරීම මගින් ආරක්ෂිත පරිසරයක් තැනීම", "සියලු නිවාසවල ජනෙල් වැසීම", "වීදි ලාම්පු නිවා දැමීම", "සියලු උද්‍යාන වැටවල් ගසා වැසීම",
        "සුරක්ෂිත හා සජීවී නාගරික අවකාශයන් සෑම පුරවැසියෙකුටම නිදහසේ ගමන් කිරීමට ඉඩ සලසයි."),
      q(t, "'ලෝක ජනගහන දිනය' (World Population Day) එක්සත් ජාතීන් විසින් සෑම වසරකම සමරනු ලබන්නේ කවදාද?",
        "ජූලි 11 වන දින (1987 ජූලි 11 දින ලෝක ජනගහනය බිලියන 5 ඉක්මවීම සිහිපත් කරමින්)", "ජනවාරි 1 වන දින", "දෙසැම්බර් 25 වන දින", "අප්‍රේල් 1 වන දින",
        "ජනගහන සංවර්ධනය, ප්‍රජනක සෞඛ්‍යය, ස්ත්‍රී-පුරුෂ සමානාත්මතාව හා තිරසාර සම්පත් කළමනාකරණය පිළිබඳ දැනුවත් කිරීම මෙහි අරමුණයි."),
      q(t, "'ජනගහන වයස්ගත වීම' පිළිබඳව චීනය මෑතකදී තම ජනගහන ප්‍රතිපත්තිය වෙනස් කළේ කෙසේද?",
        "එක් දරු ප්‍රතිපත්තිය අහෝසි කර පළමුව දරුවන් දෙදෙනෙකුටත් පසුව 2021 දී දරුවන් තිදෙනෙකු දක්වාත් ඉඩ දෙමින් උපත් දිරිමත් කිරීමේ ප්‍රතිපත්තිවලට මාරු විය", "ළමුන් සිටීම සම්පූර්ණයෙන් තහනම් කළේය", "මරණ අනුපාතය වැඩි කළේය", "සියලු පාසල් වසා දැමීය",
        "එසේ වුවද නාගරික ජීවන හා අධ්‍යාපන වියදම් ඉහළ නිසා චීනයේ උපත් අනුපාතය තවමත් පහළ මට්ටමක පවතී."),
      q(t, "ජනාවාස භූගෝල විද්‍යාවේ 'සේවා ආර්ථික නගර' (Resort & Tourism Towns - උදා: නුවරඑළිය, ඇල්ල, නීස්, ක්වීන්ස්ටවුන්) බිහිවන්නේ කුමන සාධක මතද?",
        "සිසිල් දේශගුණය, සුන්දර කඳු හෝ වෙරළ භූ දර්ශන, වනජීවී හා සංස්කෘතික උරුමයන් ආශ්‍රිත ආකර්ෂණය මත", "විශාල ගල් අඟුරු පතල් මත", "රසායනික කර්මාන්තශාලා මත", "වැලි කාන්තාර පමණක් මත",
        "මෙම නගරවල අධික හෝටල් ඉදිකිරීම් පරිසරයට හා ස්වාභාවික සුන්දරත්වයට හානි නොවන පරිදි පාලනය කළ යුතුය."),
      q(t, "'ද්විත්ව බර' (Double Burden of Malnutrition / Disease) සංවර්ධනය වෙමින් පවතින ජනගහන අතර දක්නට ලැබෙන්නේ කෙසේද?",
        "එකම රටක හෝ ප්‍රජාවක එක් පසෙකින් මන්දපෝෂණය හා බෝවන රෝගද, අනෙක් පසින් නාගරික ජීවන රටාව නිසා ඇතිවන තරබාරුකම හා දියවැඩියාව වැනි රෝගද එකවර පැවතීම", "සියලු දෙනා අධික බර වීම පමණි", "කිසිදු රෝගයක් නැති වීම", "ළමුන් පමණක් රෝගී වීම",
        "සෞඛ්‍ය හා පෝෂණ ප්‍රතිපත්ති සැලසුම් කිරීමේදී මෙම ද්විත්ව අභියෝගයට මුහුණ දීමට සිදුවේ."),
      q(t, "'පදිංචි හා රැකියා ස්ථාන විමධ්‍යගත කිරීම' (Decentralization) මහා නගරවල ජීවන තත්ත්වය වැඩි දියුණු කරන්නේ කෙසේද?",
        "රජයේ අමාත්‍යාංශ, විශ්වවිද්‍යාල හා ව්‍යාපාර උද්‍යාන තදාසන්න හෝ ප්‍රාදේශීය නගරවලට ගෙන යාමෙන් මධ්‍යම නගරයේ වාහන තදබදය හා ඉඩම් පීඩනය අඩු කිරීම", "සියලු කාර්යාල එකම ගොඩනැගිල්ලට දැමීම", "බස් රථ නැවැත්වීම", "වීදි පටු කිරීම",
        "බත්තරමුල්ල හා පැලවත්ත ප්‍රදේශවලට රජයේ ආයතන ගෙන යාම කොළඹ කොටුවේ තදබදය අඩු කිරීමේ පියවරකි."),
      q(t, "ජනගහනයේ 'දළ මරණ අනුපාතය' (Crude Death Rate) සමහර සංවර්ධිත යුරෝපීය රටවල (උදා: ජර්මනිය ~12/1000) සංවර්ධනය වෙමින් පවතින තරුණ රටකට (උදා: කටාර් ~1.5/1000) වඩා වැඩි අගයක් පෙන්වන්නේ ඇයි?",
        "සංවර්ධිත රටවල ආයු අපේක්ෂාව ඉහළ වුවද සමස්ත ජනගහනයෙන් ඉතා විශාල ප්‍රතිශතයක් වයස 70–85 ඉක්මවූ වැඩිහිටියන් වීම නිසා", "සංවර්ධිත රටවල රෝහල් නොමැති නිසා", "කටාර්හි මිනිසුන් අමරණීය නිසා", "ජර්මනියේ යුද්ධ පවතින නිසා",
        "එබැවින් සෞඛ්‍ය තත්ත්වය සංසන්දනය කිරීමට CDR වෙනුවට වයස්-ප්‍රමිතිගත මරණ අනුපාත හෝ IMR හා ආයු අපේක්ෂාව භාවිත කෙරේ."),
      q(t, "'අවිධිමත් ජනාවාසවල ආපදා අවදානම' (Disaster Vulnerability in Slums) ඉහළ මට්ටමක පවතින්නේ ඇයි?",
        "ඒවා බොහෝ විට නායයෑම් අවදානම් දළ බෑවුම්, ගංගා ඉවුරු, ඇළ මාර්ග රක්ෂිත හෝ අඩු බිම්වල දුර්වල අමුද්‍රව්‍යවලින් ඉදි කර ඇති බැවින්", "ඒවා කොන්ක්‍රීට් බංකර් වීම නිසා", "ඒවා ආරක්ෂිත කඳු සානුවල ඇති නිසා", "ඒවායේ හිම පතනය අඩු නිසා",
        "එබැවින් අධික වර්ෂාවකදී හෝ භූ කම්පනයකදී වැඩිම ජීවිත හා දේපළ හානිය මෙම ප්‍රජාවන්ට සිදුවේ."),
      q(t, "'ශ්‍රී ලංකාවේ ග්‍රාමීය ජනාවාස සංවර්ධන ව්‍යාපෘති' අතර 'ගම නැගුම / ප්‍රාදේශීය යටිතල පහසුකම්' මගින් අත්කර ගත් ප්‍රධාන භූගෝලීය වෙනස කුමක්ද?",
        "ග්‍රාමීය මාර්ග කොන්ක්‍රීට්/තාර දැමීම, විදුලිය, පානීය ජල ව්‍යාපෘති හා පාසල් වැඩිදියුණු වී ගම හා නගරය අතර සේවා පරතරය අඩු වීම", "සියලු ගම් නැති වී යාම", "ගොවිතැන තහනම් වීම", "ගංගා සිඳී යාම",
        "ග්‍රාමීය මාර්ග ජාලය දියුණු වීම නිසා කෘෂි නිෂ්පාදන වෙළඳපොළට ගෙන යාම ඉක්මන් හා ලාභදායී විය."),
      q(t, "'මහා ජන සංක්‍රමණ රළ' (Great Migration Waves) ඉතිහාසයේදී නව මහාද්වීපවල ජනගහනය වෙනස් කළේ කෙසේද? (උදා: 19 වන සියවසේ යුරෝපීය සංක්‍රමණය)",
        "මිලියන ගණනක් යුරෝපීයයන් උතුරු හා දකුණු ඇමරිකාවටත් ඔස්ට්‍රේලියාවටත් සංක්‍රමණය වී එම ප්‍රදේශවල ජන සංයුතිය, භාෂා හා නාගරික ව්‍යුහය සම්පූර්ණයෙන් වෙනස් කළේය", "සියලු දෙනා ඇන්ටාක්ටිකාවට ගියේය", "ආසියාව ජනශූන්‍ය විය", "යුරෝපයේ නගර අතුරුදහන් විය",
        "අද වන විටත් ඇමරිකාවේ, කැනඩාවේ, ආර්ජන්ටිනාවේ හා ඔස්ට්‍රේලියාවේ සංස්කෘතික හා ජන විකාශන පදනම එම සංක්‍රමණ මගින් සැකසී ඇත."),
      q(t, "නගරයක 'රථවාහන තදබදය පාලනය කිරීමේදී' ලන්ඩන්, සිංගප්පූරුව හා ස්ටොක්හෝම් නගර සාර්ථකව භාවිත කළ ක්‍රමවේදය කුමක්ද?",
        "නගර මධ්‍යයට පෞද්ගලික මෝටර් රථ ඇතුළු කිරීම සඳහා තදබද ගාස්තු (Congestion Pricing / ERP) අය කර එම ආදායමෙන් පොදු බස් හා දුම්රිය සේවා නවීකරණය කිරීම", "සියලු මාර්ග වැසීම", "දුම්රිය සේවා අවලංගු කිරීම", "ඉන්ධන නොමිලේ දීම",
        "මෙමගින් රථවාහන ධාවන වේගය වැඩි වූ අතර වායු දූෂණය සැලකිය යුතු ලෙස පහත වැටුණි."),
      q(t, "'දැනුම මත පදනම් වූ ආර්ථිකයේ' (Knowledge Economy) ශ්‍රම බලකාය ගොඩනැගීමට රටක් ජනගහනය තුළ ආයෝජනය කළ යුතු ප්‍රධාන ක්ෂේත්‍ර මොනවාද?",
        "විද්‍යා-තාක්ෂණ-ඉංජිනේරු-ගණිත (STEM) අධ්‍යාපනය, වෘත්තීය පුහුණුව, ඩිජිටල් සාක්ෂරතාව, පර්යේෂණ හා නවෝත්පාදන", "නුපුහුණු කම්කරු වැඩ පමණි", "ගල් ආයුධ නිෂ්පාදනය", "පාසල් අවුරුදු 3 කට සීමා කිරීම",
        "මිනිස් ප්‍රාග්ධනය (Human Capital) ගුණාත්මකව ඉහළ නැංවීම ස්වාභාවික සම්පත් අඩු රටවලට පවා ඉහළ සංවර්ධනයක් ලබා දෙයි."),
      q(t, "'අවම ඉඩම් ප්‍රමාණයක වැඩි ආහාර නිෂ්පාදනය කරන නාගරික කෘෂිකර්මය' (Urban Agriculture / Vertical Farming) ජනාවාසවලට වැදගත් වන්නේ ඇයි?",
        "ගොඩනැගිලි වහල මත හා සිරස් හරිතාගාරවල එළවළු වගා කිරීමෙන් නගරයට ප්‍රවාහන දුර (Food Miles) අඩු කර නැවුම් ආහාර සැපයීම", "නගරයේ හාල් මිල 10 ගුණයකින් වැඩි කිරීම", "සියලු උද්‍යාන කොන්ක්‍රීට් කිරීම", "ගොවීන්ට තහනම් කිරීම",
        "සිංගප්පූරුව 2030 වන විට සිය පෝෂණ අවශ්‍යතාවයෙන් 30% ක් දේශීයව හා නාගරික ගොවිපළවලින් නිපදවීමට ඉලක්ක කරයි."),
      q(t, "'ජනගහන ව්‍යාප්තියේ උන්නතාංශ බලපෑම' (Effect of Altitude on Population) අනුව ඇන්ඩීස් හා ඉතියෝපියානු උස්බිම්වල ජනාවාස පහත් බිම්වලට වඩා ඉහළ කඳුකරයේ (මීටර් 2,000–3,600) පිහිටා ඇත්තේ ඇයි?",
        "සමකාසන්න නිවර්තන කලාපයේ පහත් බිම් අධික උණුසුම, තෙතමනය හා මැලේරියා රෝග බහුල වන විට උස් සානුවල සෞම්‍ය සිසිල් දේශගුණයක් පවතින බැවින්", "කඳු මුදුනේ ඔක්සිජන් 100% ක් ඇති නිසා", "පහත් බිම් සම්පූර්ණයෙන් හිමෙන් වැසී ඇති නිසා", "මුහුද කඳු මුදුනේ ඇති නිසා",
        "බොගෝටා (කොලොම්බියාව), ක්විටෝ (ඉක්වදෝරය), ලා පාස් (බොලිවියාව) හා අඩිස් අබාබා මීට ප්‍රධාන උදාහරණ වේ."),
      q(t, "'ප්‍රජා පාදක සංවර්ධනය' (Community-Based Planning) නාගරික හා ග්‍රාමීය ජනාවාස ව්‍යාපෘති සාර්ථක වීමට හේතු වන්නේ කෙසේද?",
        "ප්‍රදේශයේ පදිංචි ජනතාවගේ සැබෑ අවශ්‍යතා (පානීය ජලය, පාසල්, පාරවල්, ආපදා ආරක්ෂාව) සැලසුම් කිරීමට ඔවුන්වම සම්බන්ධ කර ගැනීමෙන් ව්‍යාපෘතිවල තිරසාරභාවය රැකෙන බැවින්", "පිටස්තරයන්ගේ අදහස් පමණක් බලෙන් ක්‍රියාත්මක කිරීමෙන්", "ජනතාවගෙන් තොරතුරු සැඟවීමෙන්", "සියලු සැලසුම් නවතා දැමීමෙන්",
        "සහභාගීත්ව සංවර්ධන ප්‍රවේශය මගින් ප්‍රජා අයිතිවාසිකම් හා වගකීම ශක්තිමත් වේ."),
      q(t, "'ජනගහනයේ වාර්ගික හා භාෂාමය විවිධත්වය' රටක සංස්කෘතික හා ආර්ථික භූගෝල විද්‍යාවට සම්බන්ධ වන්නේ කෙසේද?",
        "සියලු ප්‍රජාවන්ට සමාන අවස්ථා, අධ්‍යාපන හා සන්නිවේදන පහසුකම් සැලසීමෙන් සමාජ සංහිඳියාව, සංචාරක ආකර්ෂණය හා ජාතික සංවර්ධනය ශක්තිමත් කළ හැකි බැවින්", "විවිධ භාෂා තහනම් කිරීමෙන්", "සංස්කෘතික උත්සව නැවැත්වීමෙන්", "නගර වසා දැමීමෙන්",
        "ස්විට්සර්ලන්තය, කැනඩාව, සිංගප්පූරුව හා ශ්‍රී ලංකාව වැනි බහු-සංස්කෘතික රටවල සමානාත්මතාවය ස්ථාවර සංවර්ධනයට පදනම වේ."),
      q(t, "'ග්‍රාමීය නේවාසික ජනාවාසවල වැසිකිළි හා පිරිසිදු පානීය ජල ප්‍රවේශය' (WASH - Water, Sanitation and Hygiene) මගින් ජනගහන සංඛ්‍යාලේඛනවලට ඇති කරන සෘජු බලපෑම කුමක්ද?",
        "පාචනය, කොලරාව හා ටයිපොයිඩ් වැනි ජලයෙන් බෝවන රෝග අඩු වී ළදරු මරණ අනුපාතය (IMR) තියුණු ලෙස පහත වැටීම", "ජන ඝනත්වය බිංදුව වීම", "උපත් අනුපාතය ශුන්‍ය වීම", "කෘෂිකර්මය නතර වීම",
        "එක්සත් ජාතීන්ගේ SDG 6 ඉලක්කය යටතේ සැමට පිරිසිදු ජලය හා සනීපාරක්ෂාව තහවුරු කිරීම ප්‍රමුඛ කාර්යයකි."),
      q(t, "'අර්ධ නාගරිකකරණය' (Peri-urbanization) තුළ කෘෂිකාර්මික බිම් කඩිනමින් වෙළඳ හා නේවාසික බිම් බවට පත්වීම නිසා පරිසරයට ඇති වන අහිතකර බලපෑම කුමක්ද?",
        "කුඹුරු හා තෙත් බිම් ගොඩකිරීම නිසා නාගරික ගංවතුර වැඩිවීම, දේශීය එළවළු නිෂ්පාදනය අඩුවීම සහ ජෛව විවිධත්වය අහිමි වීම", "වනාන්තර වැඩි වීම", "වී නිෂ්පාදනය දෙගුණ වීම", "භූගත ජලය වැඩිවීම",
        "ශ්‍රී ලංකාවේ කඩුවෙල, හෝමාගම, මීගමුව හා ගාල්ල තදාසන්න පෙදෙස්වල කුඹුරු ගොඩකිරීම නීතියෙන් නියාමනය කිරීමට සිදුව ඇත."),
      q(t, "ජනගහන භූගෝල විද්‍යාවේ 'අනාගත ශ්‍රම වෙළඳපොළ හා කෘත්‍රිම බුද්ධිය / ස්වයංක්‍රීයකරණය' (Automation & AI) නාගරික රැකියා රටාවට බලපාන්නේ කෙසේද?",
        "සාමාන්‍ය දිනචර්යාත්මක කර්මාන්තශාලා හා ලිපිකරු රැකියා අඩු වී මෘදුකාංග, දත්ත විශ්ලේෂණ, නඩත්තු, සෞඛ්‍ය හා නිර්මාණශීලී සේවා රැකියා සඳහා ඉල්ලුම වැඩි වීම", "සියලු මිනිසුන් ගොවිතැනට පමණක් යාම", "අධ්‍යාපනය අවශ්‍ය නොවීම", "පරිගණක තහනම් වීම",
        "එබැවින් ජීවිත කාලය පුරාම නව කුසලතා ඉගෙනීම (Lifelong Learning & Reskilling) නූතන ශ්‍රම බලකායට අත්‍යවශ්‍ය වේ."),
      q(t, "'කුඩා නගර' (Small Towns) වල සිට 'මහා නගර' වෙත සිදුවන අභ්‍යන්තර සංක්‍රමණය අඩු කිරීම සඳහා කෘෂිකාර්මික අගය එකතු කිරීම (Agro-processing) වැදගත් වන්නේ ඇයි?",
        "අමු කෘෂි භෝග ගමේදීම පිරිසැකසුම් කර ඇසුරුම් කිරීමෙන් ග්‍රාමීය තරුණ තරුණියන්ට ගම තුළම ඉහළ ආදායම් ලබන නව රැකියා බිහිවන බැවින්", "ගොවීන්ගේ ආදායම අඩු කිරීමට", "අස්වැන්න විනාශ කිරීමට", "ප්‍රවාහන ගාස්තු වැඩි කිරීමට",
        "පලතුරු යුෂ, කුළුබඩු සැකසීම, කිරි නිෂ්පාදන හා කාබනික ඇසුරුම් කර්මාන්ත ග්‍රාමීය ආර්ථිකය ශක්තිමත් කරයි."),
      q(t, "'ජනගහන ඝනත්වය' සහ 'ජනගහන ප්‍රමාණය' අතර වෙනස පැහැදිලි කරන හොඳම යුගල උදාහරණය කුමක්ද?",
        "රුසියාවේ ජනගහන ප්‍රමාණය විශාල වුවද (~මිලියන 144) විශාල භූමිය නිසා ජන ඝනත්වය අඩුය (~9/km²); සිංගප්පූරුවේ ජනගහනය (~මිලියන 6) කුඩා වුවද කුඩා භූමිය නිසා ජන ඝනත්වය ඉතා ඉහළය (~8,300/km²)", "රුසියාවේ ජන ඝනත්වය ලොව වැඩිමය", "සිංගප්පූරුවේ ජනගහනය බිලියනයකි", "දෙකම සමාන වේ",
        "ජනගහන සංඛ්‍යාව පමණක් බැලීමෙන් භූමිය මත පවතින ජන පීඩනය හඳුනා ගත නොහැකි අතර ඒ සඳහා ජන ඝනත්වය ගණනය කළ යුතුය."),
      q(t, "'මුහුදු බඩ තැනිතලා' හා 'ගංගා ඩෙල්ටා' ලෝක ඉතිහාසයේ සිටම විශාල ශිෂ්ටාචාර හා ජනාවාස බිහි කළ ප්‍රධාන භූමි වූයේ ඇයි?",
        "පැතලි භූමිය මත මාර්ග හා නගර ඉදිකිරීම පහසු වීම, නිරන්තර ගංවතුරෙන් අලුත් සාරවත් දියළු පස ලැබීම, පානීය/වාරි ජලය හා ජල ප්‍රවාහනය පහසු වීම", "කඳු නැගීම පහසු බැවින්", "හිම පතනය නිසා", "ගිනිකඳු අළු පමණක් නිසා",
        "නයිල්, මෙසපොතේමියා, ඉන්දු හා හොවැංහෝ ගංගා නිම්න ශිෂ්ටාචාර මීට ඓතිහාසික සාක්ෂි සපයයි."),
      q(t, "නාගරික භූගෝල විද්‍යාවේ 'සේවා ප්‍රමුඛත්වය' අනුව ශ්‍රී ලංකාවේ 'අනුරාධපුරය' සහ 'මහනුවර' නගර හඳුන්වනු ලබන්නේ කුමන ප්‍රධාන ප්‍රවර්ගය යටතේද?",
        "ඓතිහාසික, ආගමික හා සංස්කෘතික උරුම නගර (මෙන්ම පරිපාලන හා සංචාරක මධ්‍යස්ථාන)", "ඛනිජ තෙල් පිරිපහදු නගර", "බර වානේ කාර්මික නගර", "ධ්‍රැව පර්යේෂණ නගර",
        "යුනෙස්කෝ ලෝක උරුම ස්ථාන වීම නිසා මෙම නගරවල නවීන සංවර්ධනය පුරාවිද්‍යාත්මක උරුමයන් ආරක්ෂා වන පරිදි සැලසුම් කෙරේ.")
